import { Router, type Request, type Response } from "express";
import { db, getAllEvents, getEventById, insertEvent } from "../db/analytics-events-table";

export const router = Router();

// GET /tracking-api/events - Retrieve all events
router.get("/events", (req: Request, res: Response) => {
  try {
    const events = getAllEvents();
    return res.json(events);
  } catch (error) {
    return res.status(500).json({ error: "Failed to retrieve events" });
  }
});

// GET /tracking-api/events/:id - Retrieve a specific event by ID
router.get("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const event = getEventById(id);
    if (!event) {
      return res.status(404).json({ error: "Event not found" });
    }

    return res.json(event);
  } catch (error) {
    return res.status(500).json({ error: "Failed to retrieve event" });
  }
});

// POST /tracking-api/events - Create a new event
router.post("/events", (req: Request, res: Response) => {
  try {
    const { timestamp, eventType, userAgent, ipAddress, pageUrl, referrer } = req.body;

    // Validate required fields
    if (!timestamp || !eventType || !userAgent || !ipAddress || !pageUrl) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const eventId = insertEvent(
      timestamp,
      eventType,
      userAgent,
      ipAddress,
      pageUrl,
      referrer
    );

    return res.status(201).json({ id: eventId });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create event" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply data ownership checks to POST requests to the tracking endpoint
  if (req.method !== "POST" || req.path !== "/track") {
    next();
    return;
  }

  // Check if the request has a valid authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not set" });
    return;
  }

  // Verify the token signature
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const providedSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, providedSignature);
    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Widget {
  id: string;
  title: string;
  type: 'visitors' | 'goals';
  config: {
    refreshInterval?: number;
    goalId?: string;
  };
}

export function AnalyticsDashboard() {
  const [widgets, setWidgets] = useState<Widget[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchWidgets();
  }, []);

  const fetchWidgets = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/tracking-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch widgets: ${response.status}`);
      }
      const data = await response.json();
      setWidgets(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleAddWidget = async () => {
    try {
      const response = await fetch('/api/tracking-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: 'New Widget',
          type: 'visitors',
          config: {}
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to add widget: ${response.status}`);
      }

      await fetchWidgets();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteWidget = async (id: string) => {
    try {
      const response = await fetch(`/api/tracking-api/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error(`Failed to delete widget: ${response.status}`);
      }

      await fetchWidgets();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Analytics Dashboard</h1>

      <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'center' }}>
        <button 
          onClick={handleAddWidget}
          style={{
            padding: '10px 20px',
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Add New Widget
        </button>
      </div>

      {widgets.length === 0 ? (
        <p style={{ textAlign: 'center', color: '#666' }}>No widgets found. Click "Add New Widget" to get started.</p>
      ) : (
        <div style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '20px',
          justifyContent: 'center'
        }}>
          {widgets.map(widget => (
            <div 
              key={widget.id} 
              style={{
                border: '1px solid #ddd',
                borderRadius: '8px',
                padding: '15px',
                width: '300px',
                backgroundColor: '#f9f9f9'
              }}
            >
              <h3>{widget.title}</h3>
              <p>Type: {widget.type}</p>
              <p>Config: {JSON.stringify(widget.config)}</p>
              <button 
                onClick={() => handleDeleteWidget(widget.id)}
                style={{
                  marginTop: '10px',
                  padding: '5px 10px',
                  backgroundColor: '#dc3545',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Delete Widget
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

