import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST, PUT, DELETE requests to commerce routes
  const isCommerceRoute = req.path.startsWith('/api/commerce');
  const isProtectedMethod = ['POST', 'PUT', 'DELETE'].includes(req.method);

  if (!isCommerceRoute || !isProtectedMethod) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token validation (in a real system, you'd decode and verify JWT)
  const expectedToken = createHmac('sha256', secret).update(req.method + req.path).digest('hex');

  try {
    const expectedBuffer = Buffer.from(expectedToken);
    const actualBuffer = Buffer.from(token);

    if (actualBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    const isValid = timingSafeEqual(expectedBuffer, actualBuffer);

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

