    if (!existingFile) {
      return res.status(404).json({ error: "File not found" });
    }

    deleteFileMetadata(id);

    res.json({ message: "File metadata deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete file metadata" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply 2FA validation to POST requests to the /auth/2fa endpoint
  if (req.method !== "POST" || !req.path.startsWith("/auth/2fa")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const token = req.headers["authorization"]?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Missing authorization token" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}

import { useEffect, useState } from "react";

interface FileItem {
  id: string;
  name: string;
  size: number;
  lastModified: string;
}

export function FileBrowser() {
  const [files, setFiles] = useState<FileItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newFileName, setNewFileName] = useState("");
  const [newFileSize, setNewFileSize] = useState("");

  useEffect(() => {
    fetchFiles();
  }, []);

  const fetchFiles = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/sync-collaboration-api/files');
      if (!response.ok) {
        throw new Error(`Failed to fetch files: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setFiles(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateFile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFileName.trim() || !newFileSize) return;

    try {
      const response = await fetch('/api/sync-collaboration-api/files', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newFileName,
          size: Number(newFileSize),
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create file: ${response.status} ${response.statusText}`);
      }

      setNewFileName("");
      setNewFileSize("");
      await fetchFiles();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteFile = async (id: string) => {
    try {
      const response = await fetch(`/api/sync-collaboration-api/files/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete file: ${response.status} ${response.statusText}`);
      }

      await fetchFiles();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>File Browser</h1>

      <form onSubmit={handleCreateFile} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="File Name"
          value={newFileName}
          onChange={(e) => setNewFileName(e.target.value)}
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <input
          type="number"
          placeholder="Size (bytes)"
          value={newFileSize}
          onChange={(e) => setNewFileSize(e.target.value)}
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <button type="submit" style={{ padding: '8px', borderRadius: '4px', backgroundColor: '#007bff', color: 'white', border: 'none', cursor: 'pointer' }}>
          Create File
        </button>
      </form>

      {files.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No files found.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
          {files.map((file) => (
            <div key={file.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              minWidth: '200px',
              maxWidth: '300px',
              backgroundColor: '#f9f9f9'
            }}>
              <h3 style={{ margin: '0 0 10px 0' }}>{file.name}</h3>
              <p style={{ margin: '5px 0' }}>Size: {file.size} bytes</p>
              <p style={{ margin: '5px 0' }}>Last Modified: {new Date(file.lastModified).toLocaleString()}</p>
              <button 
                onClick={() => handleDeleteFile(file.id)}
                style={{
                  marginTop: '10px',
                  padding: '6px 10px',
                  borderRadius: '4px',
                  backgroundColor: '#dc3545',
                  color: 'white',
                  border: 'none',
                  cursor: 'pointer'
                }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("forum.db");

interface Topic {
  id: number;
  title: string;
  content: string;
  author: string;
  created_at: string;
  updated_at: string;
}

interface Post {
  id: number;
  topic_id: number;
  content: string;
  author: string;
  created_at: string;
  updated_at: string;
}

const createTopicsTable = `
  CREATE TABLE IF NOT EXISTS topics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    author TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

const createPostsTable = `
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topic_id INTEGER NOT NULL,
    content TEXT NOT NULL,
    author TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (topic_id) REFERENCES topics (id)
  )
`;

export const getAllTopics = (): Topic[] => {
  const stmt = db.prepare(`SELECT * FROM topics ORDER BY created_at DESC`);
  return stmt.all() as unknown as Topic[];
};

export const getTopicById = (id: number): Topic | undefined => {
  const stmt = db.prepare(`SELECT * FROM topics WHERE id = ?`);
  return stmt.get(id) as unknown as Topic | undefined;
};

export const insertTopic = (
  title: string,
  content: string,
  author: string
): number => {
  const stmt = db.prepare(
    `INSERT INTO topics (title, content, author, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(title, content, author);
  return Number(result.lastInsertRowid);
};

export const updateTopic = (
  id: number,
  title: string,
  content: string
): void => {
  const stmt = db.prepare(
    `UPDATE topics SET title = ?, content = ?, updated_at = datetime('now') WHERE id = ?`
  );
  stmt.run(title, content, id);
};

export const deleteTopic = (id: number): void => {
  const stmt = db.prepare(`DELETE FROM topics WHERE id = ?`);
  stmt.run(id);
};

export const getAllPostsForTopic = (topicId: number): Post[] => {
  const stmt = db.prepare(`SELECT * FROM posts WHERE topic_id = ? ORDER BY created_at ASC`);
  return stmt.all(topicId) as unknown as Post[];
};

export const insertPost = (
  topicId: number,
  content: string,
  author: string
): number => {
  const stmt = db.prepare(
    `INSERT INTO posts (topic_id, content, author, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(topicId, content, author);
  return Number(result.lastInsertRowid);
};

// Initialize tables
if (db.prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name='topics'`).get() === undefined) {
  db.exec(createTopicsTable);
  db.exec(createPostsTable);

  // Insert sample data
  const topic1Id = insertTopic(
    "Welcome to our community forum!",
    "This is the first post in our new forum. Feel free to introduce yourself.",
    "Admin"
  );

  const topic2Id = insertTopic(
    "How to get started with TypeScript?",
