  );

  insertPost(topic1Id, "Thanks for creating this space! Looking forward to engaging with everyone.", "CommunityMember");
  insertPost(topic2Id, "I recommend starting with the official TypeScript docs and then moving to practical projects.", "TypeScriptExpert");
  insertPost(topic3Id, "Don't forget about hooks and context API for state management!", "ReactEnthusiast");
}

