import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const API_KEY_HEADER = "x-api-key";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the /shorten endpoint
  if (req.method !== "POST" || req.path !== "/shorten") {
    next();
    return;
  }

  const apiKey = req.header(API_KEY_HEADER);

  // Check if API key is provided
  if (!apiKey) {
    res.status(401).json({ error: "API key required" });
    return;
  }

  // In a real implementation, we would check the API key against a database
  // For now, we'll just check if it matches a hardcoded value
  // This is a placeholder - in reality, you'd fetch from DB or env
  const expectedApiKey = process.env.API_KEY;

  if (!expectedApiKey) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Create HMAC of the expected key for comparison
  const expectedHmac = createHmac("sha256", expectedApiKey)
    .update(apiKey)
    .digest();

  const providedHmac = createHmac("sha256", expectedApiKey)
    .update(apiKey)
    .digest();

  // Use timingSafeEqual to prevent timing attacks
  try {
    if (timingSafeEqual(expectedHmac, providedHmac)) {
      next();
    } else {
      res.status(401).json({ error: "Invalid API key" });
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid API key" });
  }
}

import { useEffect, useState } from "react";

interface ShortUrl {
  id: string;
  originalUrl: string;
  shortCode: string;
  visitCount: number;
}

export function ShortenerWebClient() {
  const [shortUrls, setShortUrls] = useState<ShortUrl[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newUrl, setNewUrl] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    const fetchShortUrls = async () => {
      try {
        const response = await fetch("/api/shortener-api/short-urls");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setShortUrls(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchShortUrls();
  }, [refreshKey]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUrl.trim()) return;

    try {
      const response = await fetch("/api/shortener-api/short-urls", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ originalUrl: newUrl }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create: ${response.status} ${response.statusText}`);
      }

      setNewUrl("");
      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/shortener-api/short-urls/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }

      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleVisit = async (id: string) => {
    try {
      const response = await fetch(`/api/shortener-api/short-urls/${id}/visit`, {
        method: "PUT",
      });

      if (!response.ok) {
        throw new Error(`Failed to update visit count: ${response.status} ${response.statusText}`);
      }

      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>URL Shortener</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px" }}>
        <input
          type="url"
          value={newUrl}
          onChange={(e) => setNewUrl(e.target.value)}
          placeholder="Enter long URL"
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            marginBottom: "10px",
          }}
          required
        />
        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            borderRadius: "4px",
            border: "none",
            cursor: "pointer",
          }}
        >
          Create Short Link
        </button>
      </form>

      {shortUrls.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No short URLs created yet.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {shortUrls.map((url) => (
            <div
              key={url.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: 1, minWidth: "200px", marginRight: "10px" }}>
                <div style={{ fontWeight: "bold" }}>
                  {url.shortCode}
                </div>
                <div style={{ fontSize: "0.9em", color: "#555" }}>
                  {url.originalUrl}
                </div>
                <div style={{ fontSize: "0.9em", color: "#555" }}>
                  Visits: {url.visitCount}
                </div>
              </div>
              <div
                style={{
                  display: "flex",
                  gap: "5px",
                  flexWrap: "wrap",
                }}
              >
                <button
                  onClick={() => handleVisit(url.id)}
                  style={{
                    backgroundColor: "#28a745",
                    color: "white",
                    padding: "5px 10px",
                    borderRadius: "4px",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "0.85em",
                  }}
                >
                  Visit
                </button>
                <button
                  onClick={() => handleDelete(url.id)}
                  style={{
                    backgroundColor: "#dc3545",
                    color: "white",
                    padding: "5px 10px",
                    borderRadius: "4px",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "0.85em",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

