import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE, PATCH requests to /api/
  if (!req.path.startsWith('/api/') || 
      (req.method !== 'POST' && 
       req.method !== 'PUT' && 
       req.method !== 'DELETE' && 
       req.method !== 'PATCH')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify JWT signature
  // For this example, we'll just check if it matches expected format
  const expectedToken = createHmac('sha256', secret)
    .update(req.method + req.path + Date.now())
    .digest('hex');

  const expectedBuffer = Buffer.from(expectedToken);
  const providedBuffer = Buffer.from(token);

  try {
    if (timingSafeEqual(expectedBuffer, providedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: 'Invalid token' });
    }
  } catch {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import { useEffect, useState } from "react";

interface Task {
  id: number;
  title: string;
  description: string;
  projectId: number;
  completed: boolean;
}

interface Project {
  id: number;
  name: string;
}

export function TaskBoard() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");
  const [selectedProjectId, setSelectedProjectId] = useState<number>(0);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [projectsResponse, tasksResponse] = await Promise.all([
          fetch('/api/task-api/projects'),
          fetch('/api/task-api/tasks')
        ]);

        if (!projectsResponse.ok || !tasksResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const projectsData = await projectsResponse.json();
        const tasksData = await tasksResponse.json();

        setProjects(projectsData);
        setTasks(tasksData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleAddTask = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newTaskTitle.trim()) return;

    try {
      const response = await fetch('/api/task-api/tasks', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          title: newTaskTitle,
          description: newTaskDescription,
          projectId: selectedProjectId,
          completed: false
        })
      });

      if (!response.ok) {
        throw new Error('Failed to add task');
      }

      // Refresh data
      const tasksResponse = await fetch('/api/task-api/tasks');
      const tasksData = await tasksResponse.json();
      setTasks(tasksData);

      // Reset form
      setNewTaskTitle("");
      setNewTaskDescription("");
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const toggleTaskCompletion = async (taskId: number) => {
    try {
      const task = tasks.find(t => t.id === taskId);
      if (!task) return;

      const response = await fetch(`/api/task-api/tasks/${taskId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          ...task,
          completed: !task.completed
        })
      });

      if (!response.ok) {
        throw new Error('Failed to update task');
      }

      // Refresh data
      const tasksResponse = await fetch('/api/task-api/tasks');
      const tasksData = await tasksResponse.json();
      setTasks(tasksData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const deleteTask = async (taskId: number) => {
    try {
      const response = await fetch(`/api/task-api/tasks/${taskId}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete task');
      }

      // Refresh data
      const tasksResponse = await fetch('/api/task-api/tasks');
      const tasksData = await tasksResponse.json();
      setTasks(tasksData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Task Board</h1>

      <form onSubmit={handleAddTask} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Add New Task</h2>
        <input
          type="text"
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          style={{ width: '100%', padding: '10px', marginBottom: '10px', boxSizing: 'border-box' }}
        />
        <textarea
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
          style={{ width: '100%', padding: '10px', marginBottom: '10px', boxSizing: 'border-box' }}
        />
        <select
          value={selectedProjectId}
          onChange={(e) => setSelectedProjectId(Number(e.target.value))}
          style={{ width: '100%', padding: '10px', marginBottom: '10px', boxSizing: 'border-box' }}
        >
          <option value="0">Select a project</option>
          {projects.map(project => (
            <option key={project.id} value={project.id}>{project.name}</option>
          ))}
        </select>
        <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
          Add Task
        </button>
      </form>

      <div>
        <h2>Tasks</h2>
        {tasks.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No tasks found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {tasks.map(task => (
              <div 
                key={task.id} 
                style={{ 
                  padding: '15px', 
                  border: '1px solid #ddd', 
                  borderRadius: '8px', 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center',
                  backgroundColor: task.completed ? '#f0fff0' : 'white'
                }}
              >
                <div>
                  <h3 style={{ margin: '0 0 5px 0', textDecoration: task.completed ? 'line-through' : 'none' }}>
                    {task.title}
                  </h3>
                  <p style={{ margin: '0', color: '#666' }}>
                    {task.description}
                  </p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <button 
                    onClick={() => toggleTaskCompletion(task.id)}
                    style={{ 
                      padding: '5px 10px', 
                      backgroundColor: task.completed ? '#28a745' : '#ffc107', 
                      color: 'white', 
                      border: 'none', 
                      borderRadius: '4px', 
                      cursor: 'pointer' 
                    }}
                  >
                    {task.completed ? 'Completed' : 'Mark Complete'}
                  </button>
                  <button 
                    onClick={() => deleteTask(task.id)}
                    style={{ 
                      padding: '5px 10px', 
                      backgroundColor: '#dc3545', 
                      color: 'white', 
                      border: 'none', 
                      borderRadius: '4px', 
                      cursor: 'pointer' 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Task {
  id: number;
  title: string;
  description: string;
  completed: boolean;
  projectId: number;
}

interface Project {
  id: number;
  name: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    completed BOOLEAN DEFAULT FALSE,
    projectId INTEGER,
    FOREIGN KEY (projectId) REFERENCES projects (id)
  );
`;

db.exec(initSql);

export function getAllTasks(): Task[] {
  const stmt = db.prepare(`SELECT * FROM tasks`);
  return stmt.all() as unknown as Task[];
}

export function getTaskById(id: number): Task | undefined {
  const stmt = db.prepare(`SELECT * FROM tasks WHERE id = ?`);
  return stmt.get(id) as unknown as Task | undefined;
}

export function insertTask(
  title: string,
  description: string,
  projectId: number
): number {
  const stmt = db.prepare(
    `INSERT INTO tasks (title, description, projectId) VALUES (?, ?, ?)`
  );
  const result = stmt.run(title, description, projectId);
  return Number(result.lastInsertRowid);
}

export function updateTask(
  id: number,
  title: string,
  description: string,
  completed: boolean,
  projectId: number
): void {
  const stmt = db.prepare(
    `UPDATE tasks SET title = ?, description = ?, completed = ?, projectId = ? WHERE id = ?`
  );
  stmt.run(title, description, completed, projectId, id);
}

export function deleteTask(id: number): void {
  const stmt = db.prepare(`DELETE FROM tasks WHERE id = ?`);
  stmt.run(id);
}

