import { Router, type Request, type Response } from "express";
import { db, deleteDeviceState, getAllDeviceStates, getDeviceStateById, insertDeviceState, updateDeviceState } from "../db/device-states-table";

export const router = Router();

// Get all device states
router.get("/", (req: Request, res: Response) => {
  try {
    const deviceStates = getAllDeviceStates();
    res.json(deviceStates);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve device states" });
  }
});

// Get a specific device state by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deviceState = getDeviceStateById(id);
    if (!deviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    res.json(deviceState);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve device state" });
  }
});

// Create a new device state
router.post("/", (req: Request, res: Response) => {
  try {
    const { deviceId, state, timestamp } = req.body;

    if (!deviceId || !state || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: deviceId, state, or timestamp" });
    }

    const newId = insertDeviceState(deviceId, state, timestamp);
    res.status(201).json({ id: newId, deviceId, state, timestamp });
  } catch (error) {
    res.status(500).json({ error: "Failed to create device state" });
  }
});

// Update an existing device state
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { deviceId, state, timestamp } = req.body;

    if (!deviceId || !state || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: deviceId, state, or timestamp" });
    }

    const existingDeviceState = getDeviceStateById(id);
    if (!existingDeviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    updateDeviceState(id, deviceId, state, timestamp);
    res.json({ id, deviceId, state, timestamp });
  } catch (error) {
    res.status(500).json({ error: "Failed to update device state" });
  }
});

// Delete a device state
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingDeviceState = getDeviceStateById(id);
    if (!existingDeviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    deleteDeviceState(id);
    res.json({ message: "Device state deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete device state" });
  }
});

import { useEffect, useState } from "react";

interface Device {
  id: string;
  name: string;
  type: string;
  status: "on" | "off";
}

export function DeviceDashboard() {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchDevices();
  }, []);

  const fetchDevices = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/automation-engine/");
      if (!response.ok) {
        throw new Error(`Failed to fetch devices: ${response.status}`);
      }
      const data = await response.json();
      setDevices(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const toggleDevice = async (id: string, currentStatus: "on" | "off") => {
    try {
      const response = await fetch(`/api/automation-engine/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: currentStatus === "on" ? "off" : "on" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to update device: ${response.status}`);
      }
      await fetchDevices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteDevice = async (id: string) => {
    try {
      const response = await fetch(`/api/automation-engine/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete device: ${response.status}`);
      }
      await fetchDevices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Device Dashboard</h1>
      {devices.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No devices found.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {devices.map((device) => (
            <div
              key={device.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div>
                <h3>{device.name}</h3>
                <p>Type: {device.type}</p>
                <p>Status: {device.status}</p>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <button
                  onClick={() => toggleDevice(device.id, device.status)}
                  style={{
                    backgroundColor: device.status === "on" ? "#ff4d4d" : "#50c878",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  {device.status === "on" ? "Turn Off" : "Turn On"}
                </button>
                <button
                  onClick={() => deleteDevice(device.id)}
                  style={{
                    backgroundColor: "#808080",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/product-analytics.db"
);

interface EventRow {
  id: number;
  event_type: string;
  user_id: number;
  timestamp: string;
  properties: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    properties TEXT
  )
`;

db.exec(createTableSql);

export function getAllEvents(): EventRow[] {
  const stmt = db.prepare(`SELECT * FROM events`);
  return stmt.all() as unknown as EventRow[];
}

export function getEventById(id: number): EventRow | undefined {
  const stmt = db.prepare(`SELECT * FROM events WHERE id = ?`);
  return stmt.get(id) as unknown as EventRow | undefined;
}

export function insertEvent(
  eventType: string,
  userId: number,
  timestamp: string,
  properties?: Record<string, unknown>
): number {
  const propertiesStr = properties ? JSON.stringify(properties) : null;
  const stmt = db.prepare(
    `INSERT INTO events (event_type, user_id, timestamp, properties) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(eventType, userId, timestamp, propertiesStr);
  return Number(result.lastInsertRowid);
}

export function updateEvent(
  id: number,
  eventType?: string,
  userId?: number,
  timestamp?: string,
  properties?: Record<string, unknown>
): boolean {
  const updates: string[] = [];
  const params: (string | number | null)[] = [];

  if (eventType !== undefined) {
    updates.push("event_type = ?");
    params.push(eventType);
  }

  if (userId !== undefined) {
    updates.push("user_id = ?");
    params.push(userId);
  }

  if (timestamp !== undefined) {
    updates.push("timestamp = ?");
    params.push(timestamp);
  }

  if (properties !== undefined) {
    updates.push("properties = ?");
    params.push(JSON.stringify(properties));
  }

  if (updates.length === 0) return false;

  params.push(id);

  const sql = `UPDATE events SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...params);
  return result.changes > 0;
}

export function deleteEvent(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM events WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

