import { useEffect, useState } from "react";

interface Event {
  id: string;
  name: string;
  timestamp: string;
  properties: Record<string, unknown>;
}

export function AnalyticsDashboard() {
  const [events, setEvents] = useState<Event[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newEvent, setNewEvent] = useState({
    name: "",
    properties: "{}"
  });

  useEffect(() => {
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/event-ingestion-pipeline/events");
      if (!response.ok) {
        throw new Error(`Failed to fetch events: ${response.status}`);
      }
      const data = await response.json();
      setEvents(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const properties = JSON.parse(newEvent.properties);
      const response = await fetch("/api/event-ingestion-pipeline/events", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newEvent.name,
          properties
        })
      });
      if (!response.ok) {
        throw new Error(`Failed to create event: ${response.status}`);
      }
      setNewEvent({ name: "", properties: "{}" });
      fetchEvents();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteEvent = async (id: string) => {
    try {
      const response = await fetch(`/api/event-ingestion-pipeline/events/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete event: ${response.status}`);
      }
      fetchEvents();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px"
    }}>
      <h1 style={{ textAlign: "center" }}>Analytics Dashboard</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Create New Event</h2>
        <form onSubmit={handleCreateEvent} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            placeholder="Event Name"
            value={newEvent.name}
            onChange={(e) => setNewEvent({ ...newEvent, name: e.target.value })}
            style={{ width: "100%", padding: "8px" }}
          />
          <textarea
            placeholder="Properties (JSON)"
            value={newEvent.properties}
            onChange={(e) => setNewEvent({ ...newEvent, properties: e.target.value })}
            style={{ width: "100%", padding: "8px", minHeight: "60px" }}
          />
          <button type="submit" style={{ padding: "8px 16px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px" }}>
            Create Event
          </button>
        </form>
      </div>

      <div>
        <h2>Events</h2>
        {events.length === 0 ? (
          <p style={{ textAlign: "center", color: "gray" }}>No events found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {events.map((event) => (
              <div key={event.id} style={{
