import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply access control to ticket queue related routes
  if (!req.path.startsWith("/ticket-queue") || req.method === "GET") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error: JWT secret not configured" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Extract payload and signature
  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload to check if user is agent
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString("utf-8"));

    if (decodedPayload.role !== "agent" && decodedPayload.role !== "support-staff") {
      res.status(403).json({ error: "Forbidden: Access denied for non-agent users" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}

