import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for a channel deletion endpoint
  // Assuming the path pattern is /channels/:channelId/messages/:messageId
  const pathParts = req.path.split("/");
  const isChannelDeletion = pathParts.length >= 5 && pathParts[1] === "channels" && pathParts[3] === "messages";

  if (!isChannelDeletion) {
    next();
    return;
  }

  // For demonstration purposes, we assume admin status is passed via a custom property
  // In a real implementation, this would involve actual authentication and role checking
  const isAdmin = (req as any).user?.isAdmin ?? false;

  if (!isAdmin) {
    res.status(403).json({ error: "Admin access required to delete messages" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Channel {
  id: string;
  name: string;
}

interface Message {
  id: string;
  channelId: string;
  content: string;
  timestamp: string;
}

export function ChatInterface() {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedChannelId, setSelectedChannelId] = useState<string | null>(null);
  const [newMessageContent, setNewMessageContent] = useState("");
  const [newChannelName, setNewChannelName] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch channels
  useEffect(() => {
    const fetchChannels = async () => {
      setLoading(true);
      try {
        const response = await fetch('/api/channels-api/channels');
        if (!response.ok) throw new Error('Failed to fetch channels');
        const data = await response.json();
        setChannels(data);

        // Select first channel if none selected
        if (!selectedChannelId && data.length > 0) {
          setSelectedChannelId(data[0].id);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchChannels();
  }, [selectedChannelId]);

  // Fetch messages for selected channel
  useEffect(() => {
    const fetchMessages = async () => {
      if (!selectedChannelId) return;

      setLoading(true);
      try {
        const response = await fetch(`/api/channels-api/messages/channel/${selectedChannelId}`);
        if (!response.ok) throw new Error('Failed to fetch messages');
        const data = await response.json();
        setMessages(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchMessages();
  }, [selectedChannelId]);

  const handleCreateChannel = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newChannelName.trim()) return;

    setLoading(true);
    try {
      const response = await fetch('/api/channels-api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newChannelName }),
      });

      if (!response.ok) throw new Error('Failed to create channel');

      const createdChannel = await response.json();
      setChannels([...channels, createdChannel]);
      setNewChannelName("");

      // Select newly created channel
      setSelectedChannelId(createdChannel.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedChannelId || !newMessageContent.trim()) return;

    setLoading(true);
    try {
      const response = await fetch('/api/channels-api/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          channelId: selectedChannelId,
          content: newMessageContent,
        }),
      });

      if (!response.ok) throw new Error('Failed to send message');

      const createdMessage = await response.json();
      setMessages([...messages, createdMessage]);
      setNewMessageContent("");
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Team Chat</h1>

      {error && (
        <div style={{
          backgroundColor: '#ffebee',
          color: '#c62828',
          padding: '10px',
          borderRadius: '4px',
          marginBottom: '20px',
        }}>
          Error: {error}
        </div>
      )}

      {loading && <p>Loading...</p>}

      {!loading && (
        <>
          {/* Channels List */}
          <div style={{ marginBottom: '20px' }}>
            <h2>Channels</h2>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              {channels.map(channel => (
                <button
                  key={channel.id}
                  onClick={() => setSelectedChannelId(channel.id)}
                  style={{
                    padding: '10px 15px',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    backgroundColor: selectedChannelId === channel.id ? '#007bff' : '#fff',
                    color: selectedChannelId === channel.id ? '#fff' : '#000',
                    cursor: 'pointer',
                    flex: '1 1 auto',
                    minWidth: '100px',
                  }}
                >
                  #{channel.name}
                </button>
              ))}
            </div>

            <form onSubmit={handleCreateChannel} style={{ marginTop: '10px' }}>
              <input
                type="text"
                value={newChannelName}
                onChange={(e) => setNewChannelName(e.target.value)}
                placeholder="New channel name"
                style={{
                  width: '100%',
                  padding: '10px',
                  border: '1px solid #ccc',
                  borderRadius: '4px',
                  marginBottom: '10px',
                }}
              />
              <button
                type="submit"
                style={{
                  padding: '10px 15px',
                  backgroundColor: '#28a745',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer',
                }}
              >
                Create Channel
              </button>
            </form>
          </div>

          {/* Messages Area */}
          <div>
            <h2>
              {selectedChannelId 
                ? channels.find(c => c.id === selectedChannelId)?.name || 'Channel'
                : 'Select a Channel'}
            </h2>

            {messages.length === 0 ? (
              <p>No messages yet. Be the first to post!</p>
            ) : (
              <div style={{ marginBottom: '20px' }}>
                {messages.map(message => (
                  <div
                    key={message.id}
                    style={{
                      padding: '10px',
                      borderBottom: '1px solid #eee',
                      display: 'flex',
                      justifyContent: 'space-between',
                    }}
                  >
                    <span>{message.content}</span>
                    <span style={{ color: '#666', fontSize: '0.9em' }}>
                      {formatTime(message.timestamp)}
                    </span>
                  </div>
                ))}
              </div>
            )}

            {selectedChannelId && (
              <form onSubmit={handleSendMessage}>
                <textarea
                  value={newMessageContent}
                  onChange={(e) => setNewMessageContent(e.target.value)}
                  placeholder="Type your message..."
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    marginBottom: '10px',
                    resize: 'vertical',
                  }}
                  rows={3}
                />
                <button
                  type="submit"
                  style={{
                    padding: '10px 15px',
                    backgroundColor: '#007bff',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer',
                  }}
                >
                  Send Message
                </button>
              </form>
            )}
          </div>
        </>
      )}
    </div>
  );
}

