import { useEffect, useState } from "react";

interface Player {
  id: string;
  name: string;
}

interface Room {
  code: string;
  playerCount: number;
  players: Player[];
}

export function TriviaLobby() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRoomCode, setNewRoomCode] = useState("");
  const [joinCode, setJoinCode] = useState("");

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/trivia-game-engine/rooms");
      if (!response.ok) {
        throw new Error(`Failed to fetch rooms: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomCode.trim()) return;

    try {
      const response = await fetch(`/api/trivia-game-engine/rooms`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: newRoomCode }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create room: ${response.status} ${response.statusText}`);
      }

      setNewRoomCode("");
      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleJoinRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!joinCode.trim()) return;

    try {
      const response = await fetch(`/api/trivia-game-engine/rooms/${joinCode}/player-count`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ playerCount: 1 }),
      });

      if (!response.ok) {
        throw new Error(`Failed to join room: ${response.status} ${response.statusText}`);
      }

      setJoinCode("");
      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleLeaveRoom = async (code: string) => {
    try {
      const response = await fetch(`/api/trivia-game-engine/rooms/${code}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to leave room: ${response.status} ${response.statusText}`);
      }

      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center" }}>Trivia Lobby</h1>

      <form onSubmit={handleCreateRoom} style={{ marginBottom: "20px" }}>
        <input
          type="text"
          value={newRoomCode}
          onChange={(e) => setNewRoomCode(e.target.value)}
          placeholder="Enter room code to create"
          style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
        />
        <button type="submit" style={primaryButtonStyle}>Create Room</button>
      </form>

      <form onSubmit={handleJoinRoom} style={{ marginBottom: "20px" }}>
        <input
          type="text"
          value={joinCode}
          onChange={(e) => setJoinCode(e.target.value)}
          placeholder="Enter room code to join"
          style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
        />
        <button type="submit" style={primaryButtonStyle}>Join Room</button>
      </form>

      {rooms.length === 0 ? (
        <p style={{ textAlign: "center" }}>No rooms available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {rooms.map((room) => (
            <div key={room.code} style={roomCardStyle}>
              <h3>Room: {room.code}</h3>
              <p>Players: {room.playerCount}</p>
              <p>Players in room:</p>
              <ul style={{ margin: "5px 0" }}>
                {room.players.map((player) => (
                  <li key={player.id}>{player.name}</li>
                ))}
              </ul>
              <button 
                onClick={() => handleLeaveRoom(room.code)}
                style={{ ...primaryButtonStyle, backgroundColor: "#ff6b6b" }}
              >
                Leave Room
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

