import { useEffect, useState } from "react";

export function QuestionTimer() {
  const [timeLeft, setTimeLeft] = useState<number>(10);
  const [isActive, setIsActive] = useState<boolean>(true);

  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;

    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      // Handle timer completion
      console.log("Time's up!");
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const handleReset = () => {
    setTimeLeft(10);
    setIsActive(true);
  };

  const handlePause = () => {
    setIsActive(false);
  };

  const handleStart = () => {
    setIsActive(true);
  };

  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      minHeight: "100vh",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      backgroundColor: "#f5f5f5",
      padding: "20px",
    }}>
      <div style={{
        backgroundColor: "white",
        borderRadius: "12px",
        padding: "30px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
        textAlign: "center",
        maxWidth: "400px",
        width: "100%",
      }}>
        <h1 style={{
          color: "#333",
          marginBottom: "20px",
          fontSize: "24px",
        }}>
          Next Question In:
        </h1>

        <div style={{
          fontSize: "64px",
          fontWeight: "bold",
          color: timeLeft <= 3 ? "#ff4757" : "#2ed573",
          marginBottom: "30px",
          fontFamily: "monospace",
        }}>
          {timeLeft}
        </div>

        <div style={{
          display: "flex",
          gap: "10px",
          justifyContent: "center",
          flexWrap: "wrap",
        }}>
          <button 
            onClick={handleStart}
            disabled={isActive}
            style={{
              backgroundColor: "#2ed573",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Start
          </button>

          <button 
            onClick={handlePause}
            disabled={!isActive}
            style={{
              backgroundColor: "#ffa502",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: !isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Pause
          </button>

          <button 
            onClick={handleReset}
            style={{
              backgroundColor: "#3742fa",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Reset
          </button>
        </div>
      </div>
    </div>
  );
}

import { FC, useState } from "react";

interface AnswerEntryBoxProps {
  roomId: string;
  questionId: string;
  onAnswerSubmitted: () => void;
}

export function AnswerEntryBox({
  roomId,
  questionId,
  onAnswerSubmitted
}: AnswerEntryBoxProps) {
  const [answer, setAnswer] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<null | string>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!answer.trim()) return;

    setIsSubmitting(true);
    setSubmitError(null);

    try {
      const response = await fetch(`/api/realtime-room-sync/rooms/${roomId}/questions/${questionId}/answers`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ answer: answer.trim() })
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || "Failed to submit answer");
      }

      onAnswerSubmitted();
      setAnswer("");
    } catch (error) {
      setSubmitError((error as Error).message || "An unknown error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{ maxWidth: 500, margin: "0 auto", padding: "1rem" }}>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <input
          type="text"
          value={answer}
          onChange={(e) => setAnswer(e.target.value)}
          placeholder="Enter your answer..."
          style={{
            padding: "0.75rem",
            borderRadius: "0.5rem",
            border: "1px solid #ccc",
            fontSize: "1rem",
            width: "100%"
          }}
          disabled={isSubmitting}
        />
        <button
          type="submit"
          style={{
            padding: "0.75rem",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "0.5rem",
            fontSize: "1rem",
            cursor: isSubmitting ? "not-allowed" : "pointer"
          }}
          disabled={isSubmitting}
        >
          {isSubmitting ? "Submitting..." : "Submit Answer"}
        </button>
        {submitError && (
          <div style={{ color: "red", textAlign: "center" }}>{submitError}</div>
        )}
      </form>
    </div>
  );
}

