  }

  try {
    const id = insertRecipe(title, ingredients, tags || "");
    const recipe = getRecipeById(id);

    // Update search index
    insertSearchRecipe(title, ingredients);
    createSearchIndex(id, ingredients);

    return res.status(201).json(recipe);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create recipe" });
  }
});

