    return res.status(400).json({ error: "Invalid recipe ID" });
  }

  if (!title || !ingredients) {
    return res.status(400).json({ error: "Title and ingredients are required" });
  }

  const existingRecipe = getRecipeById(id);

  if (!existingRecipe) {
    return res.status(404).json({ error: "Recipe not found" });
  }

  try {
    const updatedId = updateRecipe(id, title, ingredients, tags || "");
    const recipe = getRecipeById(updatedId);

    // Update search index
    insertSearchRecipe(title, ingredients);
    createSearchIndex(id, ingredients);

    return res.json(recipe);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update recipe" });
  }
});

