import { useEffect, useState } from "react";

interface Recipe {
  id: number;
  title: string;
  description: string;
  ingredients: string[];
  instructions: string[];
}

export function RecipeListView() {
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRecipes();
  }, []);

  const fetchRecipes = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/recipes-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch recipes: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecipes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>My Recipes</h1>

      {recipes.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No recipes found. Add your first recipe below!</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px', justifyContent: 'center' }}>
          {recipes.map(recipe => (
            <div key={recipe.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', width: '100%', maxWidth: '300px' }}>
              <h2>{recipe.title}</h2>
              <p>{recipe.description}</p>
              <h3>Ingredients:</h3>
              <ul>
                {recipe.ingredients.map((ingredient, index) => (
                  <li key={index}>{ingredient}</li>
                ))}
              </ul>
              <h3>Instructions:</h3>
              <ol>
                {recipe.instructions.map((instruction, index) => (
                  <li key={index}>{instruction}</li>
                ))}
              </ol>
            </div>
          ))}
        </div>
      )}

      <hr style={{ margin: '30px 0' }} />

      <h2 style={{ textAlign: 'center' }}>Add New Recipe</h2>
      <form onSubmit={(e) => {
        e.preventDefault();
        const formData = new FormData(e.target as HTMLFormElement);
        const newRecipe = {
          title: formData.get('title') as string,
          description: formData.get('description') as string,
          ingredients: (formData.get('ingredients') as string).split('\n').filter(Boolean),
          instructions: (formData.get('instructions') as string).split('\n').filter(Boolean)
        };

        fetch('/api/recipes-api/', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newRecipe)
        })
        .then(response => {
          if (!response.ok) {
            throw new Error(`Failed to add recipe: ${response.status} ${response.statusText}`);
          }
          return response.json();
        })
        .then(() => {
          fetchRecipes(); // Refresh the list
        })
        .catch(err => {
          setError(err instanceof Error ? err.message : 'An unknown error occurred');
        });
      }}>
        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="title">Title:</label><br />
          <input type="text" id="title" name="title" required style={{ width: '100%' }} />
        </div>

        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="description">Description:</label><br />
          <textarea id="description" name="description" required style={{ width: '100%' }} />
        </div>

        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="ingredients">Ingredients (one per line):</label><br />
          <textarea id="ingredients" name="ingredients" required style={{ width: '100%' }} />
        </div>

        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="instructions">Instructions (one per line):</label><br />
          <textarea id="instructions" name="instructions" required style={{ width: '100%' }} />
        </div>

        <button type="submit" style={{ backgroundColor: '#4CAF50', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Add Recipe</button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Recipe {
  id: number;
  title: string;
  ingredients: string[];
  categories: string[];
}

export function IngredientSearch() {
  const [ingredient, setIngredient] = useState("");
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const searchRecipes = async () => {
    if (!ingredient.trim()) {
      setRecipes([]);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const response = await fetch(`/api/recipes-api/search/${ingredient.trim()}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecipes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (ingredient.trim()) {
      searchRecipes();
    } else {
      setRecipes([]);
    }
  }, [ingredient]);

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1>Ingredient Search</h1>
