import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("hotel-housekeeping.db");

interface Room {
  id: number;
  status: "clean" | "dirty" | "occupied";
  assigned_housekeeper_id: number | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    assigned_housekeeper_id INTEGER
  )
`;

db.exec(createTableSql);

export function getAllRooms(): Room[] {
  const stmt = db.prepare("SELECT * FROM rooms");
  return stmt.all() as unknown as Room[];
}

export function getRoomById(id: number): Room | undefined {
  const stmt = db.prepare("SELECT * FROM rooms WHERE id = ?");
  return stmt.get(id) as unknown as Room | undefined;
}

export function insertRoom(status: "clean" | "dirty" | "occupied", assigned_housekeeper_id: number | null): number {
  const stmt = db.prepare(
    "INSERT INTO rooms (status, assigned_housekeeper_id) VALUES (?, ?)"
  );
  const result = stmt.run(status, assigned_housekeeper_id);
  return Number(result.lastInsertRowid);
}

export function updateRoom(id: number, status: "clean" | "dirty" | "occupied", assigned_housekeeper_id: number | null): void {
  const stmt = db.prepare(
    "UPDATE rooms SET status = ?, assigned_housekeeper_id = ? WHERE id = ?"
  );
  stmt.run(status, assigned_housekeeper_id, id);
}

export function deleteRoom(id: number): void {
  const stmt = db.prepare("DELETE FROM rooms WHERE id = ?");
  stmt.run(id);
}

