const createTableSql = `
  CREATE TABLE IF NOT EXISTS timesheets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    associate_id INTEGER NOT NULL,
    matter_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    amount REAL NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllTimesheets(): TimesheetRow[] {
  const stmt = db.prepare(`SELECT * FROM timesheets`);
  return stmt.all() as unknown as TimesheetRow[];
}

export function getTimesheetById(id: number): TimesheetRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM timesheets WHERE id = ?`
  );
  return stmt.get(id) as unknown as TimesheetRow | undefined;
}

export function insertTimesheet(
  associateId: number,
  matterId: number,
  date: string,
  amount: number
): number {
  const stmt = db.prepare(
    `INSERT INTO timesheets (associate_id, matter_id, date, amount)
     VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(associateId, matterId, date, amount);
  return Number(result.lastInsertRowid);
}

export function updateTimesheet(
  id: number,
  associateId: number,
  matterId: number,
  date: string,
  amount: number
): void {
  const stmt = db.prepare(
    `UPDATE timesheets
     SET associate_id = ?, matter_id = ?, date = ?, amount = ?
     WHERE id = ?`
  );
  stmt.run(associateId, matterId, date, amount, id);
}

export function deleteTimesheet(id: number): void {
  const stmt = db.prepare(`DELETE FROM timesheets WHERE id = ?`);
  stmt.run(id);
}

