  updateApprovalStatus
} from "../db/approvals-table";

export const router = Router();

// Get all timesheets
router.get("/", (req: Request, res: Response) => {
  try {
    const timesheets = getAllTimesheets();
    res.json(timesheets);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch timesheets" });
  }
});

// Get a specific timesheet by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const timesheet = getTimesheetById(id);
    if (!timesheet) {
      return res.status(404).json({ error: "Timesheet not found" });
    }

    res.json(timesheet);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch timesheet" });
  }
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  try {
    const { associateId, matterId, date, amount } = req.body;

    if (!associateId || !matterId || !date || !amount) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newId = insertTimesheet(associateId, matterId, date, amount);

    // Create an approval record for the new timesheet
    const approvalId = insertApproval(0, newId, "pending");

    res.status(201).json({ id: newId, approvalId });
  } catch (error) {
    res.status(500).json({ error: "Failed to create timesheet" });
  }
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { associateId, matterId, date, amount } = req.body;

    if (!associateId || !matterId || !date || !amount) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingTimesheet = getTimesheetById(id);
    if (!existingTimesheet) {
      return res.status(404).json({ error: "Timesheet not found" });
    }

    // Check if the timesheet has been approved
    const approvals = getAllApprovals();
    const approval = approvals.find(a => a.timesheetId === id);

    if (approval && approval.status !== "pending") {
      return res.status(400).json({ error: "Cannot modify an approved timesheet" });
    }

    updateTimesheet(id, associateId, matterId, date, amount);

    res.json({ message: "Timesheet updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update timesheet" });
  }
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingTimesheet = getTimesheetById(id);
    if (!existingTimesheet) {
      return res.status(404).json({ error: "Timesheet not found" });
    }

    // Check if the timesheet has been approved
    const approvals = getAllApprovals();
    const approval = approvals.find(a => a.timesheetId === id);

    if (approval && approval.status !== "pending") {
      return res.status(400).json({ error: "Cannot delete an approved timesheet" });
    }

    deleteTimesheet(id);

    res.json({ message: "Timesheet deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete timesheet" });
  }
});

