import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply approval check to POST requests to the timesheet endpoint
  if (req.method !== "POST" || !req.path.startsWith("/timesheet")) {
    next();
    return;
  }

  // Check if the request has an approval header
  const hasApproval = req.headers["x-approved-by-partner"] === "true";

  // If not approved, reject the request
  if (!hasApproval) {
    res.status(403).json({
      error: "Timesheet entry requires partner approval before submission."
    });
    return;
  }

  // If approved, continue to next middleware/route handler
  next();
}

