export function PartnerApprovalQueue() {
  const [timesheets, setTimesheets] = useState<Timesheet[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTimesheets();
  }, []);

  const fetchTimesheets = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/timesheets-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch timesheets: ${response.status}`);
      }
      const data = await response.json();
      setTimesheets(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: string) => {
    try {
      const response = await fetch(`/api/approval-guard/timesheets/${id}/approve`, {
        method: "POST",
      });
      if (!response.ok) {
        throw new Error(`Failed to approve timesheet: ${response.status}`);
      }
      // Refresh the list after approval
      await fetchTimesheets();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: string) => {
    try {
      const response = await fetch(`/api/approval-guard/timesheets/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to reject timesheet: ${response.status}`);
      }
      // Refresh the list after rejection
      await fetchTimesheets();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (timesheets.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No timesheets awaiting approval.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1>Partner Approval Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {timesheets.map((timesheet) => (
          <div
            key={timesheet.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <div>
              <strong>{timesheet.associateName}</strong> - {timesheet.date} - {timesheet.hours} hours
            </div>
            <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
              <button
                onClick={() => handleApprove(timesheet.id)}
                style={{
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Approve
              </button>
              <button
                onClick={() => handleReject(timesheet.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

