    res.json({ message: `Spot ${spotNumber} has been forced open` });
  } catch (error) {
    res.status(500).json({ error: "Failed to force open spot" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the override path
  if (req.method !== "POST" || req.path !== "/override") {
    next();
    return;
  }

  // Check if the request has the required header
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify
  // the JWT signature properly. For this simplified example, we'll just
  // check if it matches a known valid token format.
  const expectedToken = createHmac("sha256", secret)
    .update("attendant_token")
    .digest("hex");

  const tokenBuffer = Buffer.from(token);
  const expectedBuffer = Buffer.from(expectedToken);

  try {
    // Use timingSafeEqual to prevent timing attacks
    if (timingSafeEqual(tokenBuffer, expectedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
}

import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  spotNumber: string;
  startTime: string;
  endTime: string;
}

export function ReservationWidget() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newReservation, setNewReservation] = useState({
    spotNumber: "",
    startTime: "",
    endTime: ""
  });

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewReservation(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newReservation)
      });
      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }
      await fetchReservations();
      setNewReservation({ spotNumber: "", startTime: "", endTime: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Parking Reservation</h1>

