import { Router, type Request, type Response } from "express";
import {
  getAllIncidents,
  getIncidentById,
  insertIncident,
  updateIncident,
  deleteIncident
} from "../db/incidents-table";

export const router = Router();

// Get all incidents
router.get("/", (req: Request, res: Response) => {
  const incidents = getAllIncidents();
  res.json(incidents);
});

// Get incident by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid incident ID" });
  }

  const incident = getIncidentById(id);
  if (!incident) {
    return res.status(404).json({ error: "Incident not found" });
  }

  res.json(incident);
});

// Create new incident
router.post("/", (req: Request, res: Response) => {
  const { residentId, blockId, description, closed } = req.body;

  if (
    typeof residentId !== "number" ||
    typeof blockId !== "number" ||
    typeof description !== "string" ||
    typeof closed !== "boolean"
  ) {
    return res.status(400).json({
      error: "Invalid input: residentId, blockId, description, and closed are required"
    });
  }

  const id = insertIncident(residentId, blockId, description, closed);
  const newIncident = getIncidentById(id);

  if (!newIncident) {
    return res.status(500).json({ error: "Failed to create incident" });
  }

  res.status(201).json(newIncident);
});

// Update incident
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { residentId, blockId, description, closed } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid incident ID" });
  }

  if (
    typeof residentId !== "number" ||
    typeof blockId !== "number" ||
    typeof description !== "string" ||
    typeof closed !== "boolean"
  ) {
    return res.status(400).json({
      error: "Invalid input: residentId, blockId, description, and closed are required"
    });
  }

  const existingIncident = getIncidentById(id);
  if (!existingIncident) {
    return res.status(404).json({ error: "Incident not found" });
  }

  updateIncident(id, residentId, blockId, description, closed);
  const updatedIncident = getIncidentById(id);

  if (!updatedIncident) {
    return res.status(500).json({ error: "Failed to update incident" });
  }

  res.json(updatedIncident);
});

// Delete incident
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid incident ID" });
  }

  const existingIncident = getIncidentById(id);
  if (!existingIncident) {
    return res.status(404).json({ error: "Incident not found" });
  }

  deleteIncident(id);
  res.json({ message: "Incident deleted successfully" });
});

