import { useEffect, useState } from "react";

interface Incident {
  id: number;
  block: string;
  status: 'open' | 'closed';
  description: string;
  reportedAt: string;
}

export function ReportList() {
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchIncidents();
  }, []);

  const fetchIncidents = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/incidents-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch incidents: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setIncidents(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/incidents-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete incident: ${response.status} ${response.statusText}`);
      }
      fetchIncidents(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const toggleStatus = async (id: number, currentStatus: 'open' | 'closed') => {
    try {
      const response = await fetch(`/api/incidents-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          status: currentStatus === 'open' ? 'closed' : 'open'
        }),
      });
      if (!response.ok) {
        throw new Error(`Failed to update incident: ${response.status} ${response.statusText}`);
      }
      fetchIncidents(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (incidents.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No incidents found.</div>;
  }

  const groupedByBlock = incidents.reduce((acc, incident) => {
    if (!acc[incident.block]) {
      acc[incident.block] = [];
    }
    acc[incident.block].push(incident);
    return acc;
  }, {} as Record<string, Incident[]>);

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Neighborhood Watch Incident Reports</h1>
      {Object.entries(groupedByBlock).map(([block, blockIncidents]) => (
        <div key={block} style={{ marginBottom: '30px' }}>
          <h2 style={{ borderBottom: '1px solid #ccc', paddingBottom: '5px' }}>Block: {block}</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {blockIncidents.map(incident => (
              <div 
                key={incident.id} 
                style={{ 
                  border: '1px solid #ddd', 
                  borderRadius: '8px', 
                  padding: '15px', 
                  backgroundColor: incident.status === 'open' ? '#f0fff0' : '#fff0f0'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div>
                    <p><strong>Description:</strong> {incident.description}</p>
                    <p><strong>Status:</strong> {incident.status}</p>
                    <p><strong>Reported At:</strong> {new Date(incident.reportedAt).toLocaleString()}</p>
                  </div>
                  <div style={{ display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
                    <button 
                      onClick={() => toggleStatus(incident.id, incident.status)}
                      style={{ 
                        backgroundColor: '#007bff', 
                        color: 'white', 
                        border: 'none', 
                        borderRadius: '4px', 
                        padding: '5px 10px', 
                        cursor: 'pointer' 
                      }}
                    >
                      {incident.status === 'open' ? 'Close' : 'Reopen'}
                    </button>
                    <button 
                      onClick={() => handleDelete(incident.id)}
                      style={{ 
                        backgroundColor: '#dc3545', 
                        color: 'white', 
                        border: 'none', 
                        borderRadius: '4px', 
                        padding: '5px 10px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

