export const db = new DatabaseSync(":memory:");

interface Incident {
  id: number;
  residentId: number;
  blockId: number;
  description: string;
  closed: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    residentId INTEGER NOT NULL,
    blockId INTEGER NOT NULL,
    description TEXT NOT NULL,
    closed BOOLEAN NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllIncidents(): Incident[] {
  const stmt = db.prepare(`SELECT * FROM incidents`);
  return stmt.all() as unknown as Incident[];
}

export function getIncidentById(id: number): Incident | undefined {
  const stmt = db.prepare(`SELECT * FROM incidents WHERE id = ?`);
  return stmt.get(id) as unknown as Incident | undefined;
}

export function insertIncident(
  residentId: number,
  blockId: number,
  description: string,
  closed: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO incidents (residentId, blockId, description, closed) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(residentId, blockId, description, closed);
  return Number(result.lastInsertRowid);
}

export function updateIncident(
  id: number,
  residentId: number,
  blockId: number,
  description: string,
  closed: boolean
): void {
  const stmt = db.prepare(
    `UPDATE incidents SET residentId = ?, blockId = ?, description = ?, closed = ? WHERE id = ?`
  );
  stmt.run(residentId, blockId, description, closed, id);
}

export function deleteIncident(id: number): void {
  const stmt = db.prepare(`DELETE FROM incidents WHERE id = ?`);
  stmt.run(id);
}

