import { Router, type Request, type Response } from "express";
import {
  getAllFeedings,
  getFeedingById,
  insertFeeding,
  updateFeeding,
  deleteFeeding
} from "../db/feedings-table";

export const router = Router();

// GET /feedings - Get all feedings
router.get("/feedings", (req: Request, res: Response) => {
  try {
    const feedings = getAllFeedings();
    res.json(feedings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch feedings" });
  }
});

// GET /feedings/:id - Get a feeding by ID
router.get("/feedings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid feeding ID" });
    }

    const feeding = getFeedingById(id);
    if (!feeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    res.json(feeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch feeding" });
  }
});

// POST /feedings - Create a new feeding
router.post("/feedings", (req: Request, res: Response) => {
  try {
    const { animalId, time, quantity } = req.body;

    if (typeof animalId !== "number" || typeof time !== "string" || typeof quantity !== "number") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const id = insertFeeding(animalId, time, quantity);
    res.status(201).json({ id, animalId, time, quantity });
  } catch (error) {
    res.status(500).json({ error: "Failed to create feeding" });
  }
});

// PUT /feedings/:id - Update a feeding
router.put("/feedings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { animalId, time, quantity } = req.body;

    if (isNaN(id) || typeof animalId !== "number" || typeof time !== "string" || typeof quantity !== "number") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const existingFeeding = getFeedingById(id);
    if (!existingFeeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    updateFeeding(id, animalId, time, quantity);
    res.json({ id, animalId, time, quantity });
  } catch (error) {
    res.status(500).json({ error: "Failed to update feeding" });
  }
});

// DELETE /feedings/:id - Delete a feeding
router.delete("/feedings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid feeding ID" });
    }

    const existingFeeding = getFeedingById(id);
    if (!existingFeeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    deleteFeeding(id);
    res.json({ message: "Feeding deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete feeding" });
  }
});

