export const router = Router();

// Middleware to check if the keeper is a head keeper
const headKeeperCheck = (req: Request, res: Response, next: () => void) => {
  const keeperId = Number(req.params.id);

  // Get the keeper by ID
  const keeper = getKeeperById(keeperId);

  // If keeper doesn't exist, return 404
  if (!keeper) {
    return res.status(404).json({ error: "Keeper not found" });
  }

  // If the keeper is not a head keeper, reject the request
  if (keeper.role !== "head keeper") {
    return res.status(403).json({ error: "Access denied: Only head keepers can make schedule changes" });
  }

  // If the keeper is a head keeper, proceed to the next middleware/handler
  next();
};

