import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect PUT requests to the schedule endpoint
  if (req.method !== "PUT" || !req.path.startsWith("/schedule")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this exercise, we'll assume the token contains "head-keeper" as a role
  try {
    // This is a simplified approach - in reality you'd decode the JWT properly
    // and verify its signature using HMAC-SHA256 with the secret
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Compare signatures safely
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    if (expectedBuffer.length !== actualBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // In a real implementation, you'd decode the payload to check roles
    // For now, we'll just check if it contains "head-keeper"
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (decodedPayload.role !== "head-keeper") {
      res.status(403).json({ error: "Forbidden: Head keeper required" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

