import { Router, type Request, type Response } from "express";
import {
  getAllMembers,
  getMemberById,
  insertMember,
  updateMember,
  deleteMember
} from "../db/members-table";
import {
  getAllCheckins,
  getCheckinById,
  insertCheckin,
  updateCheckin,
  deleteCheckin
} from "../db/checkins-table";

export const router = Router();

// Check membership status and revoke if needed
router.post("/checkin", (req: Request, res: Response) => {
  const { dogId, memberId, timestamp } = req.body;

  if (!dogId || !memberId || !timestamp) {
    return res.status(400).json({ error: "Missing required fields: dogId, memberId, timestamp" });
  }

  const member = getMemberById(Number(memberId));
  if (!member) {
    return res.status(404).json({ error: "Member not found" });
  }

  // Check if membership is active
  if (member.membershipStatus !== "active") {
    return res.status(400).json({ error: "Membership is not active" });
  }

  // Create check-in record
  const checkinId = insertCheckin(Number(dogId), Number(memberId), timestamp);

  // Revoke membership after check-in
  updateMember(Number(memberId), member.name, "revoked");

  return res.status(201).json({
    checkinId,
    memberId: Number(memberId),
    message: "Check-in successful, membership revoked"
  });
});

// Get all members
router.get("/members", (req: Request, res: Response) => {
  const members = getAllMembers();
  return res.json(members);
});

// Get a specific member by ID
router.get("/members/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const member = getMemberById(id);

  if (!member) {
    return res.status(404).json({ error: "Member not found" });
  }

  return res.json(member);
});

// Create a new member
router.post("/members", (req: Request, res: Response) => {
  const { name, membershipStatus } = req.body;

  if (!name || !membershipStatus) {
    return res.status(400).json({ error: "Missing required fields: name, membershipStatus" });
  }

  const memberId = insertMember(name, membershipStatus);

  return res.status(201).json({
    id: memberId,
    name,
    membershipStatus
  });
});

// Update a member
router.put("/members/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, membershipStatus } = req.body;

  if (!name || !membershipStatus) {
    return res.status(400).json({ error: "Missing required fields: name, membershipStatus" });
  }

  const member = getMemberById(id);
  if (!member) {
    return res.status(404).json({ error: "Member not found" });
  }

  updateMember(id, name, membershipStatus);

  return res.json({
    id,
    name,
    membershipStatus
  });
});

// Delete a member
router.delete("/members/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const member = getMemberById(id);

  if (!member) {
    return res.status(404).json({ error: "Member not found" });
  }

  deleteMember(id);

  return res.json({ message: "Member deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
