import { useEffect, useState } from "react";

export function MobileApp() {
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newMember, setNewMember] = useState({
    name: "",
    email: "",
    dogName: "",
  });

  // Fetch members on component mount
  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/membership-api/members");
      if (!response.ok) {
        throw new Error(`Failed to fetch members: ${response.status}`);
      }
      const data = await response.json();
      setMembers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/membership-api/members", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newMember),
      });
      if (!response.ok) {
        throw new Error(`Failed to create member: ${response.status}`);
      }
      setNewMember({ name: "", email: "", dogName: "" });
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCheckIn = async (memberId: string) => {
    try {
      const response = await fetch(`/api/membership-api/checkin`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ memberId }),
      });
      if (!response.ok) {
        throw new Error(`Failed to check in: ${response.status}`);
      }
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleRevoke = async (memberId: string) => {
    try {
      const response = await fetch(`/api/membership-api/revoke/${memberId}`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to revoke membership: ${response.status}`);
      }
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (memberId: string) => {
    try {
      const response = await fetch(`/api/membership-api/members/${memberId}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete member: ${response.status}`);
      }
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={styles.container}>Loading...</div>;
  }

  if (error) {
    return <div style={styles.container}>Error: {error}</div>;
  }

  return (
    <div style={styles.container}>
      <h1>Dog Park Membership</h1>

      <h2>Add New Member</h2>
      <form onSubmit={handleCreateMember} style={styles.form}>
        <input
          type="text"
          placeholder="Name"
          value={newMember.name}
          onChange={(e) => setNewMember({...newMember, name: e.target.value})}
          style={styles.input}
        />
        <input
          type="email"
          placeholder="Email"
          value={newMember.email}
          onChange={(e) => setNewMember({...newMember, email: e.target.value})}
          style={styles.input}
        />
        <input
          type="text"
          placeholder="Dog Name"
          value={newMember.dogName}
          onChange={(e) => setNewMember({...newMember, dogName: e.target.value})}
          style={styles.input}
        />
        <button type="submit" style={styles.button}>Add Member</button>
      </form>

      <h2>Members</h2>
      {members.length === 0 ? (
        <p>No members found.</p>
      ) : (
        <div style={styles.memberList}>
          {members.map(member => (
            <div key={member.id} style={styles.memberCard}>
