import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./winery-harvest.db");

interface HarvestRecord {
  id: number;
  grapeVariety: string;
  weight: number;
  plotId: number;
  finalised: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS harvest_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    grapeVariety TEXT NOT NULL,
    weight REAL NOT NULL,
    plotId INTEGER NOT NULL,
    finalised BOOLEAN NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllHarvestRecords(): HarvestRecord[] {
  const stmt = db.prepare(`SELECT * FROM harvest_records`);
  return stmt.all() as unknown as HarvestRecord[];
}

export function getHarvestRecordById(id: number): HarvestRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM harvest_records WHERE id = ?`);
  const result = stmt.get(id) as Record<string, unknown> | undefined;

  if (!result) return undefined;

  return {
    id: result.id as number,
    grapeVariety: result.grapeVariety as string,
    weight: result.weight as number,
    plotId: result.plotId as number,
    finalised: result.finalised as boolean
  };
}

export function insertHarvestRecord(
  grapeVariety: string,
  weight: number,
  plotId: number,
  finalised: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO harvest_records (grapeVariety, weight, plotId, finalised) VALUES (?, ?, ?, ?)`
  );

  stmt.run(grapeVariety, weight, plotId, finalised);

  const lastIdResult = db.prepare(`SELECT last_insert_rowid() as id`).get();

  if (!lastIdResult || typeof lastIdResult.id !== 'number') {
    throw new Error('Failed to retrieve last inserted row ID');
  }

  return lastIdResult.id;
}

export function updateHarvestRecord(
  id: number,
  grapeVariety: string,
  weight: number,
  plotId: number,
  finalised: boolean
): void {
  const stmt = db.prepare(
    `UPDATE harvest_records SET grapeVariety = ?, weight = ?, plotId = ?, finalised = ? WHERE id = ?`
  );

  stmt.run(grapeVariety, weight, plotId, finalised, id);
}

export function deleteHarvestRecord(id: number): void {
  const stmt = db.prepare(`DELETE FROM harvest_records WHERE id = ?`);
  stmt.run(id);
}

