  getHarvestRecordById,
  insertHarvestRecord,
  updateHarvestRecord
} from "../db/harvest-records-table";

export const router = Router();

// Get all harvest records
router.get("/", (req: Request, res: Response) => {
  try {
    const records = getAllHarvestRecords();
    res.json(records);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch harvest records" });
  }
});

// Get a specific harvest record by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid record ID" });
    }

    const record = getHarvestRecordById(id);
    if (!record) {
      return res.status(404).json({ error: "Harvest record not found" });
    }

    res.json(record);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch harvest record" });
  }
});

// Create a new harvest record
router.post("/", (req: Request, res: Response) => {
  try {
    const { grapeVariety, weight, plotId, finalised } = req.body;

    if (!grapeVariety || typeof weight !== "number" || typeof plotId !== "number" || typeof finalised !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const newId = insertHarvestRecord(grapeVariety, weight, plotId, finalised);
    const createdRecord = getHarvestRecordById(newId);

    if (!createdRecord) {
      return res.status(500).json({ error: "Failed to create harvest record" });
    }

    res.status(201).json(createdRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to create harvest record" });
  }
});

// Update an existing harvest record
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid record ID" });
    }

    const { grapeVariety, weight, plotId, finalised } = req.body;

    if (!grapeVariety || typeof weight !== "number" || typeof plotId !== "number" || typeof finalised !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const existingRecord = getHarvestRecordById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Harvest record not found" });
    }

    updateHarvestRecord(id, grapeVariety, weight, plotId, finalised);
    const updatedRecord = getHarvestRecordById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to update harvest record" });
    }

    res.json(updatedRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to update harvest record" });
  }
});

