import type { Request, Response, NextFunction } from "express";
import { router as harvestRecordsRouter } from "../routes/harvest-records-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check requests to harvest records API
  if (!req.path.startsWith("/api/harvest-records")) {
    next();
    return;
  }

  // Only check POST requests to finalize a record
  if (req.method !== "POST" || !req.path.includes("/finalize")) {
    next();
    return;
  }

  // Check if user has winemaker role
  // This is a placeholder - in reality, you'd extract the user from the request
  // For example, via a JWT middleware that sets req.user
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole === "winemaker") {
    next();
  } else {
    res.status(403).json({ error: "Only winemaker role may finalise harvest records" });
  }
}

