            step="0.1"
          />
        </div>

        <div>
          <label htmlFor="plotId" style={{ display: "block", marginBottom: "5px" }}>
            Plot ID:
          </label>
          <input
            id="plotId"
            type="text"
            value={plotId}
            onChange={(e) => setPlotId(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            padding: "10px 15px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: loading ? "default" : "pointer",
            fontWeight: "bold"
          }}
        >
          {loading ? "Saving..." : "Save Harvest Record"}
        </button>

        {error && (
          <div style={{ color: "red", marginTop: "10px" }}>
            {error}
          </div>
        )}
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";

interface HarvestRecord {
  id: string;
  date: string;
  grapes: string;
  quantity: number;
  notes: string;
  finalised: boolean;
}

export function HarvestList() {
  const [records, setRecords] = useState<HarvestRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<string | null>(null);

  useEffect(() => {
    const fetchRecords = async () => {
      try {
        const response = await fetch('/api/harvest-records-api/');
        if (!response.ok) {
          throw new Error('Failed to fetch harvest records');
        }
        const data = await response.json();
        setRecords(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    // Simulate getting current user role
    setCurrentUser('winemaker');
    fetchRecords();
  }, []);

  const handleFinalise = async (id: string) => {
    try {
      const response = await fetch(`/api/harvest-records-api/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ finalised: true }),
      });

      if (!response.ok) {
        throw new Error('Failed to finalise record');
      }

      // Refresh the list
      const updatedResponse = await fetch('/api/harvest-records-api/');
      const updatedData = await updatedResponse.json();
      setRecords(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (records.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No harvest records found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Harvest Records</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {records.map((record) => (
          <div 
            key={record.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              backgroundColor: '#f9f9f9'
            }}
          >
            <div style={{ marginBottom: '10px' }}>
              <strong>Date:</strong> {record.date}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Grapes:</strong> {record.grapes}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Quantity:</strong> {record.quantity} kg
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Notes:</strong> {record.notes}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Status:</strong> {record.finalised ? 'Finalised' : 'Pending'}
            </div>
            {!record.finalised && currentUser === 'winemaker' && (
              <button 
                onClick={() => handleFinalise(record.id)}
                style={{ 
                  backgroundColor: '#4CAF50', 
                  color: 'white', 
                  border: 'none', 
                  padding: '8px 16px', 
                  borderRadius: '4px', 
                  cursor: 'pointer'
                }}
              >
                Finalise
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./winery-harvest.db");

interface HarvestRecord {
  id: number;
  grapeVariety: string;
  weight: number;
  plotId: number;
  finalised: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS harvest_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    grapeVariety TEXT NOT NULL,
    weight REAL NOT NULL,
    plotId INTEGER NOT NULL,
    finalised BOOLEAN NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllHarvestRecords(): HarvestRecord[] {
  const stmt = db.prepare(`SELECT * FROM harvest_records`);
  return stmt.all() as unknown as HarvestRecord[];
}

export function getHarvestRecordById(id: number): HarvestRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM harvest_records WHERE id = ?`);
  const result = stmt.get(id) as Record<string, unknown> | undefined;

  if (!result) return undefined;

  return {
    id: result.id as number,
    grapeVariety: result.grapeVariety as string,
    weight: result.weight as number,
    plotId: result.plotId as number,
    finalised: result.finalised as boolean
  };
}

export function insertHarvestRecord(
  grapeVariety: string,
  weight: number,
  plotId: number,
  finalised: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO harvest_records (grapeVariety, weight, plotId, finalised) VALUES (?, ?, ?, ?)`
  );

  stmt.run(grapeVariety, weight, plotId, finalised);

  const lastIdResult = db.prepare(`SELECT last_insert_rowid() as id`).get();

  if (!lastIdResult || typeof lastIdResult.id !== 'number') {
    throw new Error('Failed to retrieve last inserted row ID');
  }

  return lastIdResult.id;
}

export function updateHarvestRecord(
  id: number,
  grapeVariety: string,
  weight: number,
  plotId: number,
  finalised: boolean
): void {
  const stmt = db.prepare(
    `UPDATE harvest_records SET grapeVariety = ?, weight = ?, plotId = ?, finalised = ? WHERE id = ?`
  );

  stmt.run(grapeVariety, weight, plotId, finalised, id);
}

export function deleteHarvestRecord(id: number): void {
  const stmt = db.prepare(`DELETE FROM harvest_records WHERE id = ?`);
  stmt.run(id);
}

