export function getAllBoxContents(): BoxContentsRow[] {
  const stmt = db.prepare(`
    SELECT member_id, week_date, contents
    FROM box_contents
  `);
  return stmt.all() as unknown as BoxContentsRow[];
}

export function getBoxContentsByMemberAndWeek(
  memberId: number,
  weekDate: string
): BoxContentsRow | undefined {
  const stmt = db.prepare(`
    SELECT member_id, week_date, contents
    FROM box_contents
    WHERE member_id = ? AND week_date = ?
  `);
  return stmt.get(memberId, weekDate) as unknown as BoxContentsRow | undefined;
}

export function insertBoxContents(
  memberId: number,
  weekDate: string,
  contents: string
): number {
  const stmt = db.prepare(`
    INSERT OR REPLACE INTO box_contents (member_id, week_date, contents)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(memberId, weekDate, contents);
  return Number(result.lastInsertRowid);
}

export function updateBoxContents(
  memberId: number,
  weekDate: string,
  contents: string
): number {
  const stmt = db.prepare(`
    UPDATE box_contents
    SET contents = ?
    WHERE member_id = ? AND week_date = ?
  `);
  const result = stmt.run(contents, memberId, weekDate);
  return Number(result.changes);
}

export function deleteBoxContents(
  memberId: number,
  weekDate: string
): number {
  const stmt = db.prepare(`
    DELETE FROM box_contents
    WHERE member_id = ? AND week_date = ?
  `);
  const result = stmt.run(memberId, weekDate);
  return Number(result.changes);
}

