import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBoxContents,
  getAllBoxContents,
  getBoxContentsByMemberAndWeek,
  insertBoxContents,
  updateBoxContents
} from "../db/box-contents-table";

export const router = Router();

// Get all box contents
router.get("/", (req: Request, res: Response) => {
  try {
    const contents = getAllBoxContents();
    res.json(contents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch box contents" });
  }
});

// Get box contents by member and week
router.get("/:memberId/:weekDate", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);
  const weekDate = req.params.weekDate;

  if (isNaN(memberId)) {
    return res.status(400).json({ error: "Invalid member ID" });
  }

  try {
    const content = getBoxContentsByMemberAndWeek(memberId, weekDate);
    if (!content) {
      return res.status(404).json({ error: "Box contents not found" });
    }
    res.json(content);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch box contents" });
  }
});

// Create new box contents
router.post("/", (req: Request, res: Response) => {
  const { memberId, weekDate, contents } = req.body;

  if (!memberId || !weekDate || !contents) {
    return res.status(400).json({ error: "Missing required fields: memberId, weekDate, contents" });
  }

  try {
    const newId = insertBoxContents(Number(memberId), weekDate, contents);
    res.status(201).json({ id: newId, memberId, weekDate, contents });
  } catch (error) {
    res.status(500).json({ error: "Failed to create box contents" });
  }
});

// Update box contents
router.put("/:memberId/:weekDate", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);
  const weekDate = req.params.weekDate;
  const { contents } = req.body;

  if (isNaN(memberId)) {
    return res.status(400).json({ error: "Invalid member ID" });
  }

  if (!contents) {
    return res.status(400).json({ error: "Missing required field: contents" });
  }

  try {
    const updatedRows = updateBoxContents(memberId, weekDate, contents);
    if (updatedRows === 0) {
      return res.status(404).json({ error: "Box contents not found" });
    }
    res.json({ message: "Box contents updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update box contents" });
  }
});

// Delete box contents
router.delete("/:memberId/:weekDate", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);
  const weekDate = req.params.weekDate;

  if (isNaN(memberId)) {
    return res.status(400).json({ error: "Invalid member ID" });
  }

  try {
    const deletedRows = deleteBoxContents(memberId, weekDate);
    if (deletedRows === 0) {
      return res.status(404).json({ error: "Box contents not found" });
    }
    res.json({ message: "Box contents deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete box contents" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the lock endpoint
  if (req.method !== "POST" || req.path !== "/lock") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(expectedSignature, "base64url"),
    Buffer.from(actualSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Decode payload to check role
  try {
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    if (decodedPayload.role !== "staff") {
      res.status(403).json({ error: "Access denied: staff only" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token payload" });
  }
}

import { useEffect, useState } from "react";

interface BoxItem {
  id: string;
  name: string;
  description: string;
}

interface SelectedItem {
  id: string;
  name: string;
  weekDate: string;
}

export function BoxCustomizer() {
  const [items, setItems] = useState<BoxItem[]>([]);
  const [selectedItems, setSelectedItems] = useState<SelectedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId] = useState("123"); // In a real app, this would come from auth
  const [weekDate] = useState(new Date().toISOString().split('T')[0]); // Today's date

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(`/api/box-api/`);
        if (!response.ok) throw new Error(`Failed to fetch items: ${response.status}`);
        const data = await response.json();
        setItems(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const fetchSelectedItems = async () => {
      try {
        const response = await fetch(`/api/box-api/${memberId}/${weekDate}`);
        if (!response.ok) throw new Error(`Failed to fetch selected items: ${response.status}`);
        const data = await response.json();
        setSelectedItems(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    };

    fetchSelectedItems();
  }, [memberId, weekDate]);

  const handleSelectItem = async (item: BoxItem) => {
    try {
      const response = await fetch(`/api/box-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          memberId,
          weekDate,
          itemId: item.id,
          itemName: item.name
        })
      });

      if (!response.ok) throw new Error(`Failed to select item: ${response.status}`);

      // Refresh data
      const itemsResponse = await fetch(`/api/box-api/`);
      const itemsData = await itemsResponse.json();
      setItems(itemsData);

      const selectedResponse = await fetch(`/api/box-api/${memberId}/${weekDate}`);
      const selectedData = await selectedResponse.json();
      setSelectedItems(selectedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeselectItem = async (itemId: string) => {
    try {
      const response = await fetch(`/api/box-api/${memberId}/${weekDate}/${itemId}`, {
        method: "DELETE"
      });

      if (!response.ok) throw new Error(`Failed to deselect item: ${response.status}`);

      // Refresh data
      const itemsResponse = await fetch(`/api/box-api/`);
      const itemsData = await itemsResponse.json();
      setItems(itemsData);

      const selectedResponse = await fetch(`/api/box-api/${memberId}/${weekDate}`);
      const selectedData = await selectedResponse.json();
      setSelectedItems(selectedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Weekly Box Customization</h1>

      <h2>Available Items</h2>
      {items.length === 0 ? (
        <p>No items available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {items.map(item => (
            <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "10px", flex: "1 1 200px" }}>
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <button 
                onClick={() => handleSelectItem(item)}
                style={{ backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", padding: "5px 10px", cursor: "pointer" }}
              >
                Add to Box
              </button>
            </div>
          ))}
        </div>
      )}

      <h2>Selected Items</h2>
      {selectedItems.length === 0 ? (
        <p>No items selected for this week.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {selectedItems.map(item => (
            <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "10px", flex: "1 1 200px" }}>
              <h3>{item.name}</h3>
              <button 
                onClick={() => handleDeselectItem(item.id)}
                style={{ backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", padding: "5px 10px", cursor: "pointer" }}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

