      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  if (boxContents.length === 0) {
    return (
      <div style={{ textAlign: 'center', padding: '20px' }}>
        No box contents available.
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Staff Lock Screen</h1>
      <p style={{ textAlign: 'center', marginBottom: '30px' }}>
        Finalize the week's box contents
      </p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {boxContents.map((item) => (
          <div 
            key={`${item.memberId}-${item.weekDate}`}
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              display: 'flex',
              flexDirection: 'column',
              gap: '10px',
            }}
          >
            <div style={{ fontWeight: 'bold' }}>
              Member ID: {item.memberId}
            </div>
            <div>
              Week Date: {item.weekDate}
            </div>
            <div>
              Contents: {item.contents.join(', ')}
            </div>
            <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
              <button 
                onClick={() => finalizeWeek(item.memberId, item.weekDate)}
                style={{
                  backgroundColor: '#4CAF50',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  padding: '8px 16px',
                  cursor: 'pointer',
                }}
              >
                Finalize
              </button>
              <button 
                onClick={() => deleteBoxContent(item.memberId, item.weekDate)}
                style={{
                  backgroundColor: '#f44336',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  padding: '8px 16px',
                  cursor: 'pointer',
                }}
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

