    equipment_id INTEGER NOT NULL,
    artist_id INTEGER NOT NULL,
    return_time TEXT
  )
`;

db.exec(createTableSql);

export function getAllCheckouts(): EquipmentCheckout[] {
  const stmt = db.prepare(`SELECT * FROM equipment_checkouts`);
  return stmt.all() as unknown as EquipmentCheckout[];
}

export function getCheckoutById(id: number): EquipmentCheckout | undefined {
  const stmt = db.prepare(
    `SELECT * FROM equipment_checkouts WHERE id = ?`
  );
  return stmt.get(id) as EquipmentCheckout | undefined;
}

export function insertCheckout(
  equipmentId: number,
  artistId: number,
  returnTime: string | null
): number {
  const stmt = db.prepare(
    `INSERT INTO equipment_checkouts (equipment_id, artist_id, return_time) VALUES (?, ?, ?)`
  );
  const result = stmt.run(equipmentId, artistId, returnTime);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(
  id: number,
  equipmentId: number,
  artistId: number,
  returnTime: string | null
): void {
  const stmt = db.prepare(
    `UPDATE equipment_checkouts SET equipment_id = ?, artist_id = ?, return_time = ? WHERE id = ?`
  );
  stmt.run(equipmentId, artistId, returnTime, id);
}

