export function ToolCheckoutUi() {
  const [checkouts, setCheckouts] = useState<ToolCheckout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/tool-checkouts-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setCheckouts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleRetire = async (id: string) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ returnDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the list after successful update
      await fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the list after successful deletion
      await fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  if (checkouts.length === 0) {
    return (
      <div style={{ textAlign: 'center', padding: '20px' }}>
        No tool checkouts found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Tool Checkout Tracker</h1>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ borderBottom: '1px solid #ccc' }}>
            <th style={{ textAlign: 'left', padding: '10px' }}>Member</th>
            <th style={{ textAlign: 'left', padding: '10px' }}>Tool</th>
            <th style={{ textAlign: 'left', padding: '10px' }}>Checkout Date</th>
            <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {checkouts.map((checkout) => (
            <tr key={checkout.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '10px' }}>{checkout.memberName}</td>
              <td style={{ padding: '10px' }}>{checkout.toolName}</td>
              <td style={{ padding: '10px' }}>{new Date(checkout.checkoutDate).toLocaleDateString()}</td>
              <td style={{ padding: '10px' }}>
                <button 
                  onClick={() => handleRetire(checkout.id)}
                  style={{ 
                    backgroundColor: '#4CAF50', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer', 
                    marginRight: '10px'
                  }}
                >
                  Retire
                </button>
                <button 
                  onClick={() => handleDelete(checkout.id)}
                  style={{ 
                    backgroundColor: '#f44336', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer'
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

