import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Book {
  id: number;
  title: string;
  author: string;
  read: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    read BOOLEAN DEFAULT FALSE
  );
`;

db.exec(createTableSql);

export const getAllBooks = (): Book[] => {
  const stmt = db.prepare(`SELECT * FROM books`);
  return stmt.all() as unknown as Book[];
};

export const getBookById = (id: number): Book | undefined => {
  const stmt = db.prepare(`SELECT * FROM books WHERE id = ?`);
  return stmt.get(id) as unknown as Book | undefined;
};

export const insertBook = (title: string, author: string, read: boolean): number => {
  const stmt = db.prepare(`INSERT INTO books (title, author, read) VALUES (?, ?, ?)`);
  const result = stmt.run(title, author, read);
  return Number(result.lastInsertRowid);
};

export const updateBook = (id: number, title: string, author: string, read: boolean): void => {
  const stmt = db.prepare(`UPDATE books SET title = ?, author = ?, read = ? WHERE id = ?`);
  stmt.run(title, author, read, id);
};

export const deleteBook = (id: number): void => {
  const stmt = db.prepare(`DELETE FROM books WHERE id = ?`);
  stmt.run(id);
};

