import { Router, type Request, type Response } from "express";
import { db, deleteBook, getAllBooks, getBookById, insertBook, updateBook } from "../db/books-table";

export const router = Router();

// Get all books
router.get("/", (req: Request, res: Response) => {
  const books = getAllBooks();
  res.json(books);
});

// Get a book by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const book = getBookById(id);

  if (!book) {
    return res.status(404).json({ error: "Book not found" });
  }

  res.json(book);
});

// Create a new book
router.post("/", (req: Request, res: Response) => {
  const { title, author, read } = req.body;

  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  const newId = insertBook(title, author, read || false);
  const newBook = getBookById(newId);

  if (!newBook) {
    return res.status(500).json({ error: "Failed to create book" });
  }

  res.status(201).json(newBook);
});

// Update a book
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, author, read } = req.body;

  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  const existingBook = getBookById(id);

  if (!existingBook) {
    return res.status(404).json({ error: "Book not found" });
  }

  updateBook(id, title, author, read || false);
  const updatedBook = getBookById(id);

  if (!updatedBook) {
    return res.status(500).json({ error: "Failed to update book" });
  }

  res.json(updatedBook);
});

// Delete a book
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const existingBook = getBookById(id);

  if (!existingBook) {
    return res.status(404).json({ error: "Book not found" });
  }

  deleteBook(id);
  res.json({ message: "Book deleted successfully" });
});

import { useEffect, useState } from "react";

interface Book {
