import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  description: string;
  isbn: string;
}

export function BookCatalog() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newBook, setNewBook] = useState<Omit<Book, "id">>({ 
    title: "", 
    author: "", 
    description: "", 
    isbn: ""
  });

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/books-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch books: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddBook = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/books-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newBook),
      });
      if (!response.ok) {
        throw new Error(`Failed to add book: ${response.status}`);
      }
      const createdBook = await response.json();
      setBooks([...books, createdBook]);
      setNewBook({ title: "", author: "", description: "", isbn: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteBook = async (id: number) => {
    try {
      const response = await fetch(`/api/books-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete book: ${response.status}`);
      }
      setBooks(books.filter(book => book.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    maxWidth: "600px",
    margin: "0 auto 20px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
    boxSizing: "border-box",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
  };

  const gridStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "20px",
    justifyContent: "center",
    maxWidth: "1200px",
    margin: "0 auto",
  };

  const cardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "250px",
    boxSizing: "border-box",
    backgroundColor: "#f9f9f9",
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif", padding: "20px" }}>
      <h1 style={{ textAlign: "center" }}>Book Catalog</h1>

      <form onSubmit={handleAddBook} style={formStyle}>
        <input
          type="text"
          placeholder="Title"
          value={newBook.title}
          onChange={(e) => setNewBook({...newBook, title: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Author"
          value={newBook.author}
          onChange={(e) => setNewBook({...newBook, author: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Description"
          value={newBook.description}
          onChange={(e) => setNewBook({...newBook, description: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="ISBN"
          value={newBook.isbn}
          onChange={(e) => setNewBook({...newBook, isbn: e.target.value})}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>Add Book</button>
      </form>

      <div style={gridStyle}>
        {books.length === 0 ? (
          <p style={{ textAlign: "center", width: "100%" }}>No books available.</p>
        ) : (
          books.map((book) => (
            <div key={book.id} style={cardStyle}>
              <h3>{book.title}</h3>
              <p><strong>Author:</strong> {book.author}</p>
              <p><strong>Description:</strong> {book.description}</p>
              <p><strong>ISBN:</strong> {book.isbn}</p>
              <button 
                onClick={() => handleDeleteBook(book.id)}
                style={{ ...buttonStyle, backgroundColor: "#dc3545" }}
              >
                Delete
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

