import { useEffect, useState } from "react";

interface Stop {
  id: number;
  name: string;
  notes: string;
}

export function StopNoteEditor() {
  const [stops, setStops] = useState<Stop[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [notes, setNotes] = useState<{[key: number]: string}>({});

  useEffect(() => {
    fetchStops();
  }, []);

  const fetchStops = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/trip-api/stops');
      if (!response.ok) {
        throw new Error(`Failed to fetch stops: ${response.status}`);
      }
      const data = await response.json();
      setStops(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const handleSave = async (id: number) => {
    try {
      const response = await fetch(`/api/trip-api/stops/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          notes: notes[id],
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update stop: ${response.status}`);
      }

      // Refresh the stops list after saving
      await fetchStops();
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleChange = (id: number, value: string) => {
    setNotes(prev => ({
      ...prev,
      [id]: value
    }));
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Stop Notes</h1>
      {stops.length === 0 ? (
        <p>No stops found.</p>
      ) : (
        <div>
          {stops.map(stop => (
            <div key={stop.id} style={{ marginBottom: '20px', border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <h3>{stop.name}</h3>
              {editingId === stop.id ? (
                <>
                  <textarea
                    value={notes[stop.id] || stop.notes}
                    onChange={(e) => handleChange(stop.id, e.target.value)}
                    style={{ width: '100%', height: '100px', marginBottom: '10px' }}
                  />
                  <button 
                    onClick={() => handleSave(stop.id)}
                    style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px', cursor: 'pointer' }}
                  >
                    Save
                  </button>
                  <button 
                    onClick={() => setEditingId(null)}
                    style={{ backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px', marginLeft: '10px', cursor: 'pointer' }}
                  >
                    Cancel
                  </button>
                </>
              ) : (
                <>
                  <p>{stop.notes || 'No notes yet.'}</p>
                  <button 
                    onClick={() => {
                      setEditingId(stop.id);
                      setNotes(prev => ({
                        ...prev,
                        [stop.id]: stop.notes
                      }));
                    }}
                    style={{ backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px', cursor: 'pointer' }}
                  >
                    Edit Note
                  </button>
                </>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

