import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, deskId, date } = req.body;

    if (!memberId || !deskId || !date) {
      return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
    }

    const id = insertBooking(memberId, deskId, date);
    const newBooking = getBookingById(id);

    if (!newBooking) {
      return res.status(500).json({ error: "Failed to create booking" });
    }

    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, deskId, date } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!memberId || !deskId || !date) {
      return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, memberId, deskId, date);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
    }

    res.json(updatedBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    // In a real application, we would verify supervisor role here
    // For now, we'll just proceed with deletion
    deleteBooking(id);
    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check for DELETE requests to booking routes
  if (req.method !== "DELETE" || !req.path.startsWith("/bookings/")) {
    next();
    return;
  }

  // Check if user has supervisor role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal server error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  // For this example, we'll assume the token contains role info in a known format
  try {
    // This is a simplified check - in reality, you'd decode the JWT and verify its signature
    // using HMAC-SHA256 with the secret
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (expectedSignature.length !== actualSignature.length || 
        !timingSafeEqual(expectedSignature, actualSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // In a real implementation, you would decode the token to check the role
    // For now, we'll just simulate checking the role
    const decodedToken = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    if (decodedToken.role !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor role required to delete bookings" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

