import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("housekeeping.db");

interface RoomRow {
  id: number;
  status: string;
  author_role: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    author_role TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRooms(): RoomRow[] {
  const stmt = db.prepare("SELECT * FROM rooms");
  return stmt.all() as unknown as RoomRow[];
}

export function getRoomById(id: number): RoomRow | undefined {
  const stmt = db.prepare("SELECT * FROM rooms WHERE id = ?");
  return stmt.get(id) as RoomRow | undefined;
}

export function insertRoom(status: string, authorRole: string): number {
  const stmt = db.prepare(
    "INSERT INTO rooms (status, author_role) VALUES (?, ?)"
  );
  const result = stmt.run(status, authorRole);
  return Number(result.lastInsertRowid);
}

export function updateRoom(id: number, status: string, authorRole: string): void {
  const stmt = db.prepare(
    "UPDATE rooms SET status = ?, author_role = ? WHERE id = ?"
  );
  stmt.run(status, authorRole, id);
}

export function deleteRoom(id: number): void {
  const stmt = db.prepare("DELETE FROM rooms WHERE id = ?");
  stmt.run(id);
}

