import { Router, type Request, type Response } from "express";
import { db, deleteRoom, getAllRooms, getRoomById, insertRoom, updateRoom } from "../db/rooms-table";

export const router = Router();

// GET /api/housekeeping-records - Get all housekeeping records
router.get("/", (req: Request, res: Response) => {
  try {
    const rooms = getAllRooms();
    res.json(rooms);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch housekeeping records" });
  }
});

// GET /api/housekeeping-records/:id - Get a specific housekeeping record by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const room = getRoomById(id);

    if (!room) {
      return res.status(404).json({ error: "Housekeeping record not found" });
    }

    res.json(room);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch housekeeping record" });
  }
});

// POST /api/housekeeping-records - Create a new housekeeping record
router.post("/", (req: Request, res: Response) => {
  try {
    const { status, authorRole } = req.body;

    if (!status || !authorRole) {
      return res.status(400).json({ error: "Status and author role are required" });
    }

    const id = insertRoom(status, authorRole);
    const newRoom = getRoomById(id);

    if (!newRoom) {
      return res.status(500).json({ error: "Failed to create housekeeping record" });
    }

    res.status(201).json(newRoom);
  } catch (error) {
    res.status(500).json({ error: "Failed to create housekeeping record" });
  }
});

// PUT /api/housekeeping-records/:id - Update an existing housekeeping record
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { status, authorRole } = req.body;

    if (!status || !authorRole) {
      return res.status(400).json({ error: "Status and author role are required" });
    }

    const existingRoom = getRoomById(id);

    if (!existingRoom) {
      return res.status(404).json({ error: "Housekeeping record not found" });
    }

    updateRoom(id, status, authorRole);
    const updatedRoom = getRoomById(id);

    if (!updatedRoom) {
      return res.status(500).json({ error: "Failed to update housekeeping record" });
    }

    res.json(updatedRoom);
  } catch (error) {
    res.status(500).json({ error: "Failed to update housekeeping record" });
  }
});

// DELETE /api/housekeeping-records/:id - Delete a housekeeping record
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const existingRoom = getRoomById(id);

    if (!existingRoom) {
      return res.status(404).json({ error: "Housekeeping record not found" });
    }

    deleteRoom(id);
    res.json({ message: "Housekeeping record deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete housekeeping record" });
  }
});

import { Router, type Request, type Response } from "express";
import { db, deleteRoom, getAllRooms, getRoomById, insertRoom, updateRoom } from "../db/rooms-table";

export const router = Router();

// Middleware to guard deletion requests from non-supervisors
const supervisorOnlyDeletionGuard = (req: Request, res: Response): Response => {
  const { authorRole } = req.body;

  if (authorRole !== "supervisor") {
    return res.status(403).json({ message: "Deletion is restricted to supervisors only." });
  }

  return res.status(200).json({ message: "Authorization granted." });
};

// Example usage of the guard in a DELETE route
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ message: "Invalid room ID." });
  }

  const room = getRoomById(id);

  if (!room) {
    return res.status(404).json({ message: "Room not found." });
  }

  // Apply the supervisor-only deletion guard
  const guardResult = supervisorOnlyDeletionGuard(req, res);

  if (guardResult.statusCode === 403) {
    return guardResult;
  }

  // Proceed with deletion if authorized
  deleteRoom(id);

  return res.status(200).json({ message: "Room deleted successfully." });
});

