import { FC, useEffect, useState } from "react";

interface SupervisorDeleteGuardProps {
  taskId: string;
}

export function SupervisorDeleteGuard({ taskId }: SupervisorDeleteGuardProps) {
  const [isSupervisor, setIsSupervisor] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkSupervisorStatus = async () => {
      try {
        const response = await fetch(`/api/supervisor-only-deletion-guard/${taskId}`);
        if (!response.ok) {
          throw new Error(`Failed to check supervisor status: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setIsSupervisor(data.isSupervisor);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    if (taskId) {
      checkSupervisorStatus();
    } else {
      setIsSupervisor(false);
      setLoading(false);
    }
  }, [taskId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (isSupervisor === null) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Unable to determine supervisor status</div>;
  }

  if (!isSupervisor) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Access denied: Only supervisors can delete this record.</div>;
  }

  return null; // Allow deletion if supervisor
}

