import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Audition {
  actor_id: number;
  show_id: number;
  signup_timestamp: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS auditions (
    actor_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    signup_timestamp INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllAuditions(): Audition[] {
  const stmt = db.prepare(`SELECT * FROM auditions;`);
  return stmt.all() as unknown as Audition[];
}

export function getAuditionById(actorId: number, showId: number): Audition | undefined {
  const stmt = db.prepare(`SELECT * FROM auditions WHERE actor_id = ? AND show_id = ?;`);
  return stmt.get(actorId, showId) as unknown as Audition | undefined;
}

export function insertAudition(actorId: number, showId: number, signupTimestamp: number): number {
  const stmt = db.prepare(`INSERT INTO auditions (actor_id, show_id, signup_timestamp) VALUES (?, ?, ?);`);
  const result = stmt.run(actorId, showId, signupTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateAudition(actorId: number, showId: number, signupTimestamp: number): number {
  const stmt = db.prepare(`UPDATE auditions SET signup_timestamp = ? WHERE actor_id = ? AND show_id = ?;`);
  const result = stmt.run(signupTimestamp, actorId, showId);
  return Number(result.changes);
}

export function deleteAudition(actorId: number, showId: number): number {
  const stmt = db.prepare(`DELETE FROM auditions WHERE actor_id = ? AND show_id = ?;`);
  const result = stmt.run(actorId, showId);
  return Number(result.changes);
}

