  if (!actorId || !showId || !signupTimestamp) {
    return res.status(400).json({ error: "Missing required fields: actorId, showId, signupTimestamp" });
  }

  try {
    const newId = insertAudition(actorId, showId, signupTimestamp);
    const newAudition = getAuditionById(actorId, showId);
    res.status(201).json(newAudition);
  } catch (error) {
    res.status(500).json({ error: "Failed to create audition" });
  }
});

