  const { signupTimestamp } = req.body;

  if (isNaN(actorId) || isNaN(showId)) {
    return res.status(400).json({ error: "Invalid actorId or showId" });
  }

  if (!signupTimestamp) {
    return res.status(400).json({ error: "Missing required field: signupTimestamp" });
  }

  try {
    const updatedRows = updateAudition(actorId, showId, signupTimestamp);
    if (updatedRows === 0) {
      return res.status(404).json({ error: "Audition not found" });
    }
    const updatedAudition = getAuditionById(actorId, showId);
    res.json(updatedAudition);
  } catch (error) {
    res.status(500).json({ error: "Failed to update audition" });
  }
});

