export function SlotGrid() {
  const [shows, setShows] = useState<Show[]>([]);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAuditions() {
      try {
        const response = await fetch("/api/auditions-api/auditions");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setShows(data.shows || []);
        setSlots(data.slots || []);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAuditions();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (shows.length === 0 && slots.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No shows or slots available.</div>;
  }

  // Group slots by show
  const slotsByShow = shows.map(show => ({
    show,
    slots: slots.filter(slot => slot.showId === show.id)
  }));

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px"
    }}>
      <h1 style={{ textAlign: "center" }}>Available Audition Slots</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        {slotsByShow.map(({ show, slots }) => (
          <div key={show.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
            <h2>{show.title}</h2>
            <p>{show.description}</p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
              {slots.length > 0 ? (
                slots.map(slot => (
                  <div 
                    key={slot.id} 
                    style={{ 
                      border: "1px solid #999", 
                      borderRadius: "4px", 
                      padding: "10px", 
                      minWidth: "120px",
                      backgroundColor: slot.actorId ? "#f0f0f0" : "#e8f5e8"
                    }}
                  >
                    <div><strong>Time:</strong> {slot.time}</div>
                    <div><strong>Status:</strong> {slot.actorId ? "Booked" : "Available"}</div>
