  const stmt = db.prepare(`SELECT * FROM incidents WHERE id = ?`);
  return stmt.get(id) as unknown as Incident | undefined;
}

export function insertIncident(
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `INSERT INTO incidents (residentId, timestamp, description) VALUES (?, ?, ?)`
  );
