import { Router, type Request, type Response } from "express";
import {
  db,
  deleteIncident,
  getAllIncidents,
  getIncidentById,
  insertIncident,
  updateIncident
} from "../db/incidents-table";

export const router = Router();

// Get all incidents
router.get("/", (req: Request, res: Response) => {
  try {
    const incidents = getAllIncidents();
    res.json(incidents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch incidents" });
  }
});

// Get incident by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const incident = getIncidentById(id);
    if (!incident) {
      return res.status(404).json({ error: "Incident not found" });
    }

    res.json(incident);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch incident" });
  }
});

// Create new incident
router.post("/", (req: Request, res: Response) => {
  try {
    const { residentId, timestamp, description } = req.body;

    if (!residentId || !timestamp || !description) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertIncident(residentId, timestamp, description);
    const newIncident = getIncidentById(id);

    if (!newIncident) {
      return res.status(500).json({ error: "Failed to create incident" });
    }

    res.status(201).json(newIncident);
  } catch (error) {
    res.status(500).json({ error: "Failed to create incident" });
  }
});

// Update incident
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { residentId, timestamp, description } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    if (!residentId || !timestamp || !description) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const rowsAffected = updateIncident(id, residentId, timestamp, description);

    if (rowsAffected === 0) {
      return res.status(404).json({ error: "Incident not found" });
    }

    const updatedIncident = getIncidentById(id);
    if (!updatedIncident) {
      return res.status(500).json({ error: "Failed to retrieve updated incident" });
    }

    res.json(updatedIncident);
  } catch (error) {
    res.status(500).json({ error: "Failed to update incident" });
  }
});

// Delete incident (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    // In a real application, we would verify supervisor role here
    // For now, we'll just proceed with deletion
    const rowsAffected = deleteIncident(id);

    if (rowsAffected === 0) {
      return res.status(404).json({ error: "Incident not found" });
    }

    res.json({ message: "Incident deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete incident" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { router as incidentsRouter } from "../routes/incidents-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests to the incidents API
  if (req.method !== "DELETE" || !req.path.startsWith("/incidents")) {
    next();
    return;
  }

  // For demonstration purposes, we'll assume all deletions are rejected
  // In a real implementation, this would check if the user has supervisor role
  // For now, we'll just reject all delete requests to incidents
  res.status(403).json({ error: "Only supervisors can delete incidents" });
}

