const createTableSql = `
  CREATE TABLE IF NOT EXISTS incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    residentId INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    description TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllIncidents(): Incident[] {
  const stmt = db.prepare(`SELECT * FROM incidents`);
  return stmt.all() as unknown as Incident[];
}

export function getIncidentById(id: number): Incident | undefined {
  const stmt = db.prepare(`SELECT * FROM incidents WHERE id = ?`);
  return stmt.get(id) as unknown as Incident | undefined;
}

export function insertIncident(
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `INSERT INTO incidents (residentId, timestamp, description) VALUES (?, ?, ?)`
  );
  const result = stmt.run(residentId, timestamp, description);
  return Number(result.lastInsertRowid);
}

export function updateIncident(
  id: number,
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `UPDATE incidents SET residentId = ?, timestamp = ?, description = ? WHERE id = ?`
  );
  const result = stmt.run(residentId, timestamp, description, id);
  return Number(result.changes);
}

export function deleteIncident(id: number): number {
  const stmt = db.prepare(`DELETE FROM incidents WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

