import { Router, type Request, type Response } from "express";
import { db, deleteFeeding, getAllFeedings, getFeedingById, insertFeeding, updateFeeding } from "../db/feedings-table";

export const router = Router();

// Get all feedings
router.get("/", (req: Request, res: Response) => {
  try {
    const feedings = getAllFeedings();
    res.json(feedings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch feedings" });
  }
});

// Get a feeding by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid feeding ID" });
    }

    const feeding = getFeedingById(id);
    if (!feeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    res.json(feeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch feeding" });
  }
});

// Create a new feeding
router.post("/", (req: Request, res: Response) => {
  try {
    const { aquariumId, animalId, time, quantity, feederId } = req.body;

    if (!aquariumId || !animalId || !time || !quantity || !feederId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newId = insertFeeding(aquariumId, animalId, time, quantity, feederId);
    const newFeeding = getFeedingById(newId);

    if (!newFeeding) {
      return res.status(500).json({ error: "Failed to create feeding" });
    }

    res.status(201).json(newFeeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to create feeding" });
  }
});

// Update a feeding
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid feeding ID" });
    }

    const { aquariumId, animalId, time, quantity, feederId } = req.body;

    if (!aquariumId || !animalId || !time || !quantity || !feederId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingFeeding = getFeedingById(id);
    if (!existingFeeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    updateFeeding(id, aquariumId, animalId, time, quantity, feederId);
    const updatedFeeding = getFeedingById(id);

    if (!updatedFeeding) {
      return res.status(500).json({ error: "Failed to update feeding" });
    }

    res.json(updatedFeeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to update feeding" });
  }
});

// Delete a feeding
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid feeding ID" });
    }

    const existingFeeding = getFeedingById(id);
    if (!existingFeeding) {
      return res.status(404).json({ error: "Feeding not found" });
    }

    // Check user role before deletion (simplified)
    const userRole = req.headers["x-user-role"];
    if (userRole !== "admin") {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    deleteFeeding(id);
    res.json({ message: "Feeding deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete feeding" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { router as feedingsApiRouter } from "../routes/feedings-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Only check requests to the feedings API
  if (!req.path.startsWith("/api/feedings")) {
    next();
    return;
  }

  // Check if user has supervisor role
  // This is a placeholder implementation - in a real app,
  // you'd extract the user from a JWT or session
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole !== "supervisor") {
    res.status(403).json({ error: "Deletion not allowed for non-supervisors" });
    return;
  }

  next();
}

