import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the user has supervisor role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole === "supervisor") {
    next();
    return;
  }

  // For non-supervisors, reject the deletion request
  res.status(403).json({ error: "Deletion not permitted for non-supervisor roles" });
}

import { useEffect, useState } from "react";

interface UsageRecord {
  id: string;
  date: string;
  kwh: number;
  cost: number;
}

export function UsageDashboard() {
  const [records, setRecords] = useState<UsageRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    date: "",
    kwh: "",
    cost: ""
  });

  useEffect(() => {
    fetchUsageRecords();
  }, []);

  const fetchUsageRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/usage-records-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewRecord({
      ...newRecord,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/usage-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: newRecord.date,
          kwh: parseFloat(newRecord.kwh),
          cost: parseFloat(newRecord.cost)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status}`);
      }

      // Reset form and reload records
      setNewRecord({ date: "", kwh: "", cost: "" });
      fetchUsageRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/usage-records-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status}`);
      }

      fetchUsageRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
      }}
    >
      <h1>My Usage Records</h1>

      {records.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>
          No usage records found.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px"
          }}
        >
          {records.map((record) => (
            <div
              key={record.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center"
              }}
            >
              <div>
                <strong>{record.date}</strong>
                <br />
                {record.kwh} kWh • ${record.cost.toFixed(2)}
              </div>
              <button
                onClick={() => handleDelete(record.id)}
                style={{
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer"
                }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: "30px" }}>Add New Record</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="date"
            name="date"
            value={newRecord.date}
            onChange={handleInputChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="number"
            name="kwh"
            placeholder="Kilowatt-hours"
            value={newRecord.kwh}
            onChange={handleInputChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="number"
            name="cost"
            placeholder="Cost in dollars"
            value={newRecord.cost}
            onChange={handleInputChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
            required
          />
        </div>
        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 15px",
            cursor: "pointer"
          }}
        >
          Add Record
        </button>
      </form>
    </div>
  );
}

import { FC, useEffect, useState } from "react";

interface AdminDeleteGuardProps {
  children: React.ReactNode;
}

export function AdminDeleteGuard({ children }: AdminDeleteGuardProps) {
  const [isSupervisor, setIsSupervisor] = useState<boolean | null>(null);

  useEffect(() => {
    const checkSupervisorStatus = async () => {
      try {
        const response = await fetch(`/api/supervisor-guard/`, {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
          },
        });

        if (response.ok) {
          const data = await response.json();
          setIsSupervisor(data.isSupervisor);
        } else {
          setIsSupervisor(false);
        }
      } catch (error) {
        setIsSupervisor(false);
      }
    };

    checkSupervisorStatus();
  }, []);

  if (isSupervisor === null) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (!isSupervisor) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Access denied. You must be a supervisor to delete records.
      </div>
    );
  }

  return <>{children}</>;
}

