}

export function SupervisorDeleteGuard({ children }: SupervisorDeleteGuardProps) {
  const [isSupervisor, setIsSupervisor] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function checkSupervisorStatus() {
      try {
        const response = await fetch("/api/member-authentication/customization");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setIsSupervisor(data.isSupervisor);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setIsSupervisor(false);
      } finally {
        setLoading(false);
      }
    }

    checkSupervisorStatus();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (isSupervisor === false) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Access denied. Only supervisors can delete items.
      </div>
    );
  }

  return <>{children}</>;
}

