import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./grants.db");

interface GrantRow {
  id: number;
  applicantId: number;
  projectDescription: string;
  requestedAmount: number;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS grants (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    applicantId INTEGER NOT NULL,
    projectDescription TEXT NOT NULL,
    requestedAmount REAL NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllGrants(): GrantRow[] {
  const stmt = db.prepare("SELECT * FROM grants");
  return stmt.all() as unknown as GrantRow[];
}

export function getGrantById(id: number): GrantRow | undefined {
  const stmt = db.prepare("SELECT * FROM grants WHERE id = ?");
  return stmt.get(id) as unknown as GrantRow | undefined;
}

export function insertGrant(
  applicantId: number,
  projectDescription: string,
  requestedAmount: number,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO grants (applicantId, projectDescription, requestedAmount, status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(applicantId, projectDescription, requestedAmount, status);
  return Number(result.lastInsertRowid);
}

export function updateGrant(
  id: number,
  applicantId: number,
  projectDescription: string,
  requestedAmount: number,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE grants SET applicantId = ?, projectDescription = ?, requestedAmount = ?, status = ? WHERE id = ?"
  );
  stmt.run(applicantId, projectDescription, requestedAmount, status, id);
}

export function deleteGrant(id: number): void {
  const stmt = db.prepare("DELETE FROM grants WHERE id = ?");
  stmt.run(id);
}

