import { Router, type Request, type Response } from "express";
import {
  deleteGrant,
  getAllGrants,
  getGrantById,
  insertGrant,
  updateGrant
} from "../db/grants-table";

export const router = Router();

router.get("/", (req: Request, res: Response) => {
  const grants = getAllGrants();
  res.json(grants);
});

router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const grant = getGrantById(id);

  if (!grant) {
    return res.status(404).json({ error: "Grant not found" });
  }

  res.json(grant);
});

router.post("/", (req: Request, res: Response) => {
  const { applicantId, projectDescription, requestedAmount, status } = req.body;

  if (
    typeof applicantId !== "number" ||
    typeof projectDescription !== "string" ||
    typeof requestedAmount !== "number" ||
    typeof status !== "string"
  ) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  const id = insertGrant(applicantId, projectDescription, requestedAmount, status);
  const newGrant = getGrantById(id);

  if (!newGrant) {
    return res.status(500).json({ error: "Failed to create grant" });
  }

  res.status(201).json(newGrant);
});

router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { applicantId, projectDescription, requestedAmount, status } = req.body;

  if (
    typeof applicantId !== "number" ||
    typeof projectDescription !== "string" ||
    typeof requestedAmount !== "number" ||
    typeof status !== "string"
  ) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  const existingGrant = getGrantById(id);

  if (!existingGrant) {
    return res.status(404).json({ error: "Grant not found" });
  }

  updateGrant(id, applicantId, projectDescription, requestedAmount, status);
  const updatedGrant = getGrantById(id);

  if (!updatedGrant) {
    return res.status(500).json({ error: "Failed to update grant" });
  }

  res.json(updatedGrant);
});

router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingGrant = getGrantById(id);

  if (!existingGrant) {
    return res.status(404).json({ error: "Grant not found" });
  }

  deleteGrant(id);

  res.json({ message: "Grant deleted successfully" });
});

