  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
  };

  const textareaStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
    minHeight: "100px",
    resize: "vertical",
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "12px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
    width: "100%",
  };

  const successMessageStyle: React.CSSProperties = {
    color: "green",
    textAlign: "center",
    marginTop: "20px",
  };

  const errorMessageStyle: React.CSSProperties = {
    color: "red",
    textAlign: "center",
    marginTop: "20px",
