router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const checkout = getCheckoutById(id);

  if (!checkout) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  res.json(checkout);
});

// Create a new checkout
router.post("/", (req: Request, res: Response) => {
  const { memberId, seedPacketId, dueDate } = req.body;

  if (!memberId || !seedPacketId || !dueDate) {
    return res.status(400).json({ error: "Member ID, seed packet ID, and due date are required" });
  }

  const newId = insertCheckout(
    Number(memberId),
    Number(seedPacketId),
    dueDate
  );

  const newCheckout = getCheckoutById(newId);

  if (!newCheckout) {
    return res.status(500).json({ error: "Failed to create checkout" });
  }

  res.status(201).json(newCheckout);
});

// Update a checkout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, seedPacketId, dueDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  if (!memberId || !seedPacketId || !dueDate) {
    return res.status(400).json({ error: "Member ID, seed packet ID, and due date are required" });
  }

  const updatedRows = updateCheckout(
    id,
    Number(memberId),
    Number(seedPacketId),
    dueDate
  );

  if (updatedRows === 0) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  const updatedCheckout = getCheckoutById(id);

  if (!updatedCheckout) {
    return res.status(500).json({ error: "Failed to retrieve updated checkout" });
  }

  res.json(updatedCheckout);
});

// Delete a checkout
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const deletedRows = deleteCheckout(id);

  if (deletedRows === 0) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  res.json({ message: "Checkout deleted successfully" });
});

