  memberId: number;
  seedPacketId: number;
  checkoutDate: string;
  dueDate: string;
  returnDate?: string | null;
}

export function CheckoutQueue() {
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/checkouts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCheckouts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReturn = async (id: number) => {
    try {
      const response = await fetch(`/api/checkouts-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ returnDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful return
      await fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/checkouts-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful deletion
      await fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (checkouts.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No checked out items found.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Seed Packet Checkout Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {checkouts.map((checkout) => (
          <div
            key={checkout.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <div>
              <p><strong>Member ID:</strong> {checkout.memberId}</p>
              <p><strong>Seed Packet ID:</strong> {checkout.seedPacketId}</p>
              <p><strong>Checkout Date:</strong> {new Date(checkout.checkoutDate).toLocaleDateString()}</p>
              <p><strong>Due Date:</strong> {new Date(checkout.dueDate).toLocaleDateString()}</p>
              {checkout.returnDate && (
                <p><strong>Return Date:</strong> {new Date(checkout.returnDate).toLocaleDateString()}</p>
              )}
            </div>
            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
              {!checkout.returnDate && (
                <button
                  onClick={() => handleReturn(checkout.id)}
                  style={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Return
                </button>
              )}
              <button
                onClick={() => handleDelete(checkout.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

