import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface ReservationRow {
  id: number;
  guestId: number;
  slotTime: string;
  staffSupervisor: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guestId INTEGER NOT NULL,
    slotTime TEXT NOT NULL,
    staffSupervisor BOOLEAN NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReservations(): ReservationRow[] {
  const stmt = db.prepare(`SELECT * FROM reservations`);
  return stmt.all() as unknown as ReservationRow[];
}

export function getReservationById(id: number): ReservationRow | undefined {
  const stmt = db.prepare(`SELECT * FROM reservations WHERE id = ?`);
  return stmt.get(id) as unknown as ReservationRow | undefined;
}

export function insertReservation(
  guestId: number,
  slotTime: string,
  staffSupervisor: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO reservations (guestId, slotTime, staffSupervisor) VALUES (?, ?, ?)`
  );
  const result = stmt.run(guestId, slotTime, staffSupervisor);
  return Number(result.lastInsertRowid);
}

export function updateReservation(
  id: number,
  guestId: number,
  slotTime: string,
  staffSupervisor: boolean
): void {
  const stmt = db.prepare(
    `UPDATE reservations SET guestId = ?, slotTime = ?, staffSupervisor = ? WHERE id = ?`
  );
  stmt.run(guestId, slotTime, staffSupervisor, id);
}

export function deleteReservation(id: number): void {
  const stmt = db.prepare(`DELETE FROM reservations WHERE id = ?`);
  stmt.run(id);
}

