import { Router, type Request, type Response } from "express";
import {
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// GET /reservations - Get all reservations
router.get("/reservations", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    return res.json(reservations);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// GET /reservations/:id - Get a specific reservation by ID
router.get("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    return res.json(reservation);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// POST /reservations - Create a new reservation
router.post("/reservations", (req: Request, res: Response) => {
  try {
    const { guestId, slotTime, staffSupervisor } = req.body;

    if (!guestId || !slotTime) {
      return res.status(400).json({ error: "Guest ID and slot time are required" });
    }

    const id = insertReservation(guestId, slotTime, staffSupervisor || false);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    return res.status(201).json(newReservation);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create reservation" });
  }
});

// PUT /reservations/:id - Update an existing reservation
router.put("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { guestId, slotTime, staffSupervisor } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    if (!guestId || !slotTime) {
      return res.status(400).json({ error: "Guest ID and slot time are required" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, guestId, slotTime, staffSupervisor || false);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    return res.json(updatedReservation);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update reservation" });
  }
});

// DELETE /reservations/:id - Delete a reservation (supervisor only)
router.delete("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    // Supervisor-only deletion logic would go here
    // For now, we'll just delete without checking supervisor status
    deleteReservation(id);

    return res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete reservation" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for a resource that requires supervisor-only deletion
  // For this implementation, we'll assume all DELETE requests to certain paths require supervisor access
  // In a real app, you'd have a more specific path pattern or route handler
  const deletePaths = ["/reservations", "/users", "/menu-items"];
  const isProtectedPath = deletePaths.some(path => req.path.startsWith(path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has supervisor role
  // This is a simplified version - in reality, you'd extract the token from headers
  // and verify it properly with HMAC-SHA256 using process.env.JWT_SECRET

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Supervisor access required" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simple verification - in practice, you'd decode and verify the JWT properly
  // This is a placeholder for demonstration purposes
  try {
    const secret = process.env.JWT_SECRET;
    if (!secret) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    // In a real implementation, you would:
    // 1. Decode the JWT (without verifying signature in this simplified version)
    // 2. Verify the signature using HMAC-SHA256 with the secret
    // 3. Check if the user has supervisor role

    // For now, we'll simulate a basic check
    const tokenParts = token.split(".");
    if (tokenParts.length < 2) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Simulate role check - in a real app, you'd decode the payload
    // and check for a supervisor role claim
    const decodedPayload = Buffer.from(tokenParts[1], "base64").toString();
    const payload = JSON.parse(decodedPayload);

    if (payload.role !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor access required for deletion" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestName: string;
  guestEmail: string;
}

interface TimeSlot {
  time: string;
  available: boolean;
}

export function ReservationCalendar() {
  const [date, setDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [guestName, setGuestName] = useState<string>('');
  const [guestEmail, setGuestEmail] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean>(false);

  useEffect(() => {
    fetchTimeSlots();
  }, [date]);

  const fetchTimeSlots = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/reservations-api/reservations?date=${date}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const reservations: Reservation[] = await response.json();

      // Generate time slots (9am to 8pm)
      const slots: TimeSlot[] = [];
      for (let hour = 9; hour <= 20; hour++) {
        const time = `${hour}:00`;
        const isAvailable = !reservations.some(r => r.time === time);
        slots.push({ time, available: isAvailable });
      }

      setTimeSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookReservation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTime || !guestName || !guestEmail) return;

    try {
      const response = await fetch('/api/reservations-api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date,
          time: selectedTime,
          guestName,
          guestEmail
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to book reservation: ${response.status} ${response.statusText}`);
      }

      setSuccess(true);
      setGuestName('');
      setGuestEmail('');
      setSelectedTime('');

      // Refresh the time slots
      await fetchTimeSlots();

      // Reset success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Book Your Reservation</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Available Time Slots</h2>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center' }}>
        {timeSlots.length > 0 ? (
          timeSlots.map((slot) => (
            <button
              key={slot.time}
              onClick={() => setSelectedTime(slot.time)}
              disabled={!slot.available}
              style={{
                padding: '10px 15px',
                borderRadius: '8px',
                border: '1px solid #ccc',
                backgroundColor: slot.available ? '#4CAF50' : '#f0f0f0',
                color: slot.available ? 'white' : 'gray',
                cursor: slot.available ? 'pointer' : 'default',
                opacity: slot.available ? 1 : 0.6,
                minWidth: '100px'
              }}
            >
              {slot.time}
            </button>
          ))
        ) : (
          <p>No time slots available for this date.</p>
        )}
      </div>

      <form onSubmit={handleBookReservation} style={{ marginTop: '30px' }}>
        <h2 style={{ textAlign: 'center' }}>Book Now</h2>

        {success && (
          <div style={{ backgroundColor: '#d4edda', color: '#155724', padding: '10px', borderRadius: '4px', marginBottom: '10px' }}>
            Reservation booked successfully!
          </div>
        )}

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Full Name:
          </label>
          <input
            type="text"
            id="name"
            value={guestName}
            onChange={(e) => setGuestName(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email Address:
          </label>
          <input
            type="email"
            id="email"
            value={guestEmail}
            onChange={(e) => setGuestEmail(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <button
          type="submit"
          disabled={!selectedTime || !guestName || !guestEmail}
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: selectedTime && guestName && guestEmail ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedTime && guestName && guestEmail ? 'pointer' : 'default'
          }}
        >
          Confirm Reservation
        </button>
      </form>
    </div>
  );
}

