// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { vendorId, stallNumber, reservedWeekendDate } = req.body;

    if (!vendorId || !stallNumber || !reservedWeekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, reservedWeekendDate"
      });
    }

    const newId = insertReservation(
      Number(vendorId),
      Number(stallNumber),
      reservedWeekendDate
    );

    const newReservation = getReservationById(newId);
    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { vendorId, stallNumber, reservedWeekendDate } = req.body;

    if (!vendorId || !stallNumber || !reservedWeekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, reservedWeekendDate"
      });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(
      id,
      Number(vendorId),
      Number(stallNumber),
      reservedWeekendDate
    );

    const updatedReservation = getReservationById(id);
    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

