export function WorkoutLog() {
  const [clients, setClients] = useState<Client[]>([]);
  const [workouts, setWorkouts] = useState<Workout[]>([]);
  const [selectedClient, setSelectedClient] = useState<string>("");
  const [date, setDate] = useState<string>("");
  const [duration, setDuration] = useState<number>(0);
  const [exercises, setExercises] = useState<Exercise[]>([
    { id: "", name: "", sets: 0, reps: 0 }
  ]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string>("");

  useEffect(() => {
    const fetchClients = async () => {
      try {
        const response = await fetch("/api/workouts-api/");
        if (!response.ok) throw new Error("Failed to fetch clients");
        const data = await response.json();
        setClients(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    };

    fetchClients();
  }, []);

  const handleAddExercise = () => {
    setExercises([...exercises, { id: "", name: "", sets: 0, reps: 0 }]);
  };

  const handleExerciseChange = (index: number, field: keyof Exercise, value: string | number) => {
    const updatedExercises = [...exercises];
    updatedExercises[index] = { ...updatedExercises[index], [field]: value };
    setExercises(updatedExercises);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedClient || !date || duration <= 0) {
      setError("Please fill in all required fields.");
      return;
    }

    try {
      const newWorkout: Omit<Workout, "id"> = {
        clientId: selectedClient,
        date,
        duration,
        exercises
      };

      const response = await fetch("/api/workouts-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newWorkout)
      });

      if (!response.ok) throw new Error("Failed to create workout");

      // Reset form
      setSelectedClient("");
      setDate("");
      setDuration(0);
      setExercises([{ id: "", name: "", sets: 0, reps: 0 }]);

      // Reload data
      const response2 = await fetch("/api/workouts-api/");
      if (response2.ok) {
        const data = await response2.json();
        setWorkouts(data);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
