import { useEffect, useState } from "react";

interface Pet {
  id: number;
  ownerName: string;
  species: string;
  notes: string;
}

interface Checkout {
  id: number;
  petId: number;
  checkoutTime: string;
}

export function CheckInOutForm() {
  const [pets, setPets] = useState<Pet[]>([]);
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [ownerName, setOwnerName] = useState("");
  const [species, setSpecies] = useState("");
  const [notes, setNotes] = useState("");

  const [editingPetId, setEditingPetId] = useState<number | null>(null);

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    try {
      setLoading(true);
      const [petsResponse, checkoutsResponse] = await Promise.all([
        fetch('/api/boarding-records-api/pets'),
        fetch('/api/boarding-records-api/checkouts')
      ]);

      if (!petsResponse.ok || !checkoutsResponse.ok) {
        throw new Error('Failed to fetch data');
      }

      const petsData = await petsResponse.json();
      const checkoutsData = await checkoutsResponse.json();

      setPets(petsData);
      setCheckouts(checkoutsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const newPet = {
        ownerName,
        species,
        notes
      };

      const response = await fetch('/api/boarding-records-api/pets', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(newPet)
      });

      if (!response.ok) {
        throw new Error('Failed to create pet record');
      }

      // Reset form
      setOwnerName("");
      setSpecies("");
      setNotes("");

      // Refresh data
      await fetchAllData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (pet: Pet) => {
    setEditingPetId(pet.id);
    setOwnerName(pet.ownerName);
    setSpecies(pet.species);
    setNotes(pet.notes);
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingPetId === null) return;

    try {
      const updatedPet = {
        ownerName,
        species,
        notes
      };

      const response = await fetch(`/api/boarding-records-api/pets/${editingPetId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updatedPet)
      });

      if (!response.ok) {
        throw new Error('Failed to update pet record');
      }

      // Reset form
      setEditingPetId(null);
      setOwnerName("");
      setSpecies("");
      setNotes("");

      // Refresh data
      await fetchAllData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/boarding-records-api/pets/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete pet record');
      }

      // Refresh data
      await fetchAllData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleCheckout = async (petId: number) => {
    try {
      const newCheckout = {
        petId,
        checkoutTime: new Date().toISOString()
      };

      const response = await fetch('/api/boarding-records-api/checkouts', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(newCheckout)
      });

      if (!response.ok) {
        throw new Error('Failed to create checkout record');
      }

      // Refresh data
      await fetchAllData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Pet Boarding Check-In/Out</h1>

      <form onSubmit={editingPetId ? handleUpdate : handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>{editingPetId ? 'Edit Pet' : 'Add New Pet'}</h2>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="ownerName" style={{ display: 'block', marginBottom: '5px' }}>Owner Name:</label>
          <input
            id="ownerName"
            type="text"
            value={ownerName}
            onChange={(e) => setOwnerName(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="species" style={{ display: 'block', marginBottom: '5px' }}>Species:</label>
          <input
            id="species"
            type="text"
            value={species}
            onChange={(e) => setSpecies(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="notes" style={{ display: 'block', marginBottom: '5px' }}>Notes:</label>
          <textarea
            id="notes"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', minHeight: '60px' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          {editingPetId ? 'Update Pet' : 'Add Pet'}
        </button>

        {editingPetId && (
          <button 
            type="button" 
            onClick={() => {
              setEditingPetId(null);
              setOwnerName("");
              setSpecies("");
              setNotes("");
            }}
            style={{ 
              backgroundColor: '#6c757d', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
              cursor: 'pointer', 
              marginLeft: '10px' 
            }}
          >
            Cancel
          </button>
        )}
      </form>

      <div style={{ marginBottom: '30px' }}>
        <h2>Pets</h2>

        {pets.length === 0 ? (
          <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No pets found.</p>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
            {pets.map(pet => (
              <div key={pet.id} style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                minWidth: '250px', 
                flex: '1 1 250px' 
