                <h3>{pet.ownerName} - {pet.species}</h3>
                <p><strong>Notes:</strong> {pet.notes}</p>
                <div style={{ marginTop: '10px', display: 'flex', gap: '5px' }}>
                  <button 
                    onClick={() => handleEdit(pet)}
                    style={{ 
                      backgroundColor: '#28a745', 
                      color: 'white', 
                      border: 'none', 
                      padding: '5px 10px', 
