                  >
                    Delete
                  </button>
                  <button 
                    onClick={() => handleCheckout(pet.id)}
                    style={{ 
                      backgroundColor: '#ffc107', 
                      color: 'black', 
                      border: 'none', 
                      padding: '5px 10px', 
                      borderRadius: '4px', 
                      cursor: 'pointer' 
                    }}
