                  <td style={{ padding: '10px' }}>{new Date(checkout.checkoutTime).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import { FC, useEffect, useState } from "react";

interface Pet {
  id: number;
  name: string;
  owner_id: number;
}

interface Checkout {
  id: number;
  pet_id: number;
  check_in_date: string;
  check_out_date: string | null;
}

export function OwnerOnlyExportButton() {
  const [pets, setPets] = useState<Pet[]>([]);
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [ownerId, setOwnerId] = useState<number>(1); // Assuming owner ID is 1 for this example

  useEffect(() => {
    const fetchData = async () => {
      try {
        const petsResponse = await fetch(`/api/boarding-records-api/pets`);
        if (!petsResponse.ok) throw new Error("Failed to fetch pets");
        const petsData = await petsResponse.json();
        setPets(petsData);

        const checkoutsResponse = await fetch(`/api/boarding-records-api/checkouts`);
        if (!checkoutsResponse.ok) throw new Error("Failed to fetch checkouts");
        const checkoutsData = await checkoutsResponse.json();
        setCheckouts(checkoutsData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleExport = () => {
    // Filter pets owned by the current owner
    const ownerPets = pets.filter(pet => pet.owner_id === ownerId);

    // Get all checkouts for these pets
    const petIds = ownerPets.map(pet => pet.id);
    const ownerCheckouts = checkouts.filter(checkout => petIds.includes(checkout.pet_id));

    // Format data for export
    const exportData = ownerPets.map(pet => {
      const petCheckouts = ownerCheckouts.filter(c => c.pet_id === pet.id);
      return {
        petName: pet.name,
        checkins: petCheckouts.map(c => ({
          checkInDate: c.check_in_date,
          checkOutDate: c.check_out_date || "Not checked out"
        }))
      };
    });

    // Create CSV content
    let csvContent = "Pet Name,Check In Date,Check Out Date\r\n";
    exportData.forEach(pet => {
      pet.checkins.forEach(checkin => {
        csvContent += `${pet.petName},${checkin.checkInDate},${checkin.checkOutDate}\r\n`;
      });
    });

    // Create download link
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "boarding_history.csv");
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "system-ui" }}>
      <h2>Owner-Only Export Button</h2>
      <p>Only the registered owner account can export the pet's full boarding history.</p>
      <button 
        onClick={handleExport}
        style={{
          backgroundColor: "#007bff",
          color: "white",
          border: "none",
          borderRadius: "4px",
          padding: "10px 20px",
          cursor: "pointer",
          fontSize: "16px"
        }}
      >
        Export Boarding History
      </button>
    </div>
  );
}

