export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
          fetch("/api/appointments-api/"),
          fetch("/api/appointments-api/time-slots"),
          fetch("/api/appointments-api/appointments"),
        ]);

        if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const doctorsData = await doctorsRes.json();
        const timeSlotsData = await timeSlotsRes.json();
        const appointmentsData = await appointmentsRes.json();

        setDoctors(doctorsData);
        setTimeSlots(timeSlotsData);
        setAppointments(appointmentsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookAppointment = async () => {
    if (!selectedDoctorId || !selectedTimeSlotId) return;

    try {
      const response = await fetch("/api/appointments-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book appointment");
      }

      // Refresh data after booking
      const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
        fetch("/api/appointments-api/"),
        fetch("/api/appointments-api/time-slots"),
        fetch("/api/appointments-api/appointments"),
      ]);

      if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const doctorsData = await doctorsRes.json();
      const timeSlotsData = await timeSlotsRes.json();
      const appointmentsData = await appointmentsRes.json();

      setDoctors(doctorsData);
      setTimeSlots(timeSlotsData);
      setAppointments(appointmentsData);

      // Reset selections
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const filteredTimeSlots = timeSlots.filter(
    (slot) => slot.doctorId === selectedDoctorId
  );

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Book an Appointment</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="doctorSelect" style={{ display: "block", marginBottom: "5px" }}>
          Select a Doctor:
        </label>
        <select
          id="doctorSelect"
          value={selectedDoctorId || ""}
          onChange={(e) => setSelectedDoctorId(Number(e.target.value))}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">Choose a doctor</option>
          {doctors.map((doctor) => (
            <option key={doctor.id} value={doctor.id}>
              {doctor.name} - {doctor.specialty}
            </option>
          ))}
        </select>
      </div>

      {selectedDoctorId && (
        <div style={{ marginBottom: "20px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>
            Select a Time Slot:
          </label>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "10px",
            }}
          >
            {filteredTimeSlots.length > 0 ? (
              filteredTimeSlots.map((slot) => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedTimeSlotId(slot.id)}
                  style={{
                    padding: "10px 15px",
                    backgroundColor: selectedTimeSlotId === slot.id ? "#007bff" : "#f8f9fa",
                    color: selectedTimeSlotId === slot.id ? "white" : "black",
                    border: "1px solid #007bff",
                    borderRadius: "4px",
                    cursor: "pointer",
                    flex: "1 1 calc(50% - 10px)",
                    minWidth: "120px",
                    textAlign: "center",
                  }}
                >
                  {slot.date} at {slot.time}
                </button>
              ))
            ) : (
              <p>No available time slots for this doctor.</p>
            )}
          </div>
        </div>
      )}

      <button
        onClick={handleBookAppointment}
        disabled={!selectedDoctorId || !selectedTimeSlotId}
        style={{
          width: "100%",
          padding: "12px",
          backgroundColor: selectedDoctorId && selectedTimeSlotId ? "#28a745" : "#6c757d",
          color: "white",
          border: "none",
          borderRadius: "4px",
          cursor: selectedDoctorId && selectedTimeSlotId ? "pointer" : "default",
        }}
      >
        Book Appointment
      </button>

      <h2 style={{ marginTop: "30px", textAlign: "center" }}>Your Appointments</h2>
      {appointments.length > 0 ? (
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            marginTop: "10px",
          }}
        >
          <thead>
            <tr>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Date</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Time</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Doctor</th>
            </tr>
          </thead>
          <tbody>
            {appointments.map((appointment) => {
              const doctor = doctors.find((doc) => doc.id === appointment.doctorId);
              return (
                <tr key={appointment.id}>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.date}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.time}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {doctor ? doctor.name : "Unknown Doctor"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p style={{ textAlign: "center", padding: "20px" }}>No appointments booked yet.</p>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Component mounts, but we don't need to fetch data for this panel
    // It just needs to trigger the export
    setLoading(false);
  }, []);

  const handleDownloadCSV = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch('/api/export-service/export/csv', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to export: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'appointment-history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <h1 style={{
        fontSize: '24px',
        fontWeight: 'bold',
        marginBottom: '20px',
        textAlign: 'center',
      }}>
        Owner-Only Export Panel
      </h1>

      <p style={{
        fontSize: '16px',
        marginBottom: '20px',
        textAlign: 'center',
      }}>
        Download a raw CSV of all appointment history.
      </p>

      <button
        onClick={handleDownloadCSV}
        disabled={loading}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          padding: '10px 20px',
          fontSize: '16px',
          cursor: loading ? 'not-allowed' : 'pointer',
          transition: 'background-color 0.2s',
        }}
      >
        {loading ? 'Exporting...' : 'Download CSV'}
      </button>

      {error && (
        <p style={{
          color: 'red',
          marginTop: '20px',
          textAlign: 'center',
        }}>
          {error}
        </p>
      )}
    </div>
  );
}

