export const db = new DatabaseSync("./rehearsals.db");

interface Rehearsal {
  id: number;
  date: string;
  time: string;
  band_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rehearsals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date TEXT NOT NULL,
    time TEXT NOT NULL,
    band_id INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRehearsals(): Rehearsal[] {
  const stmt = db.prepare("SELECT * FROM rehearsals");
  return stmt.all() as unknown as Rehearsal[];
}

export function getRehearsalById(id: number): Rehearsal | undefined {
  const stmt = db.prepare("SELECT * FROM rehearsals WHERE id = ?");
  return stmt.get(id) as unknown as Rehearsal | undefined;
}

export function insertRehearsal(
  date: string,
  time: string,
  bandId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO rehearsals (date, time, band_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(date, time, bandId);
  return Number(result.lastInsertRowid);
}

export function updateRehearsal(
  id: number,
  date: string,
  time: string,
  bandId: number
): void {
  const stmt = db.prepare(
    "UPDATE rehearsals SET date = ?, time = ?, band_id = ? WHERE id = ?"
  );
  stmt.run(date, time, bandId, id);
}

export function deleteRehearsal(id: number): void {
  const stmt = db.prepare("DELETE FROM rehearsals WHERE id = ?");
  stmt.run(id);
}

