export const db = new DatabaseSync("./orchestra.db");

interface AttendanceRow {
  musician_id: number;
  rehearsal_id: number;
  status: "present" | "absent" | "late";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS attendance (
    musician_id INTEGER NOT NULL,
    rehearsal_id INTEGER NOT NULL,
    status TEXT NOT NULL,
    PRIMARY KEY (musician_id, rehearsal_id),
    FOREIGN KEY (musician_id) REFERENCES musicians(id),
    FOREIGN KEY (rehearsal_id) REFERENCES rehearsals(id)
  )
`;

db.exec(createTableSql);

export function getAllAttendances(): AttendanceRow[] {
  const stmt = db.prepare("SELECT * FROM attendance");
  return stmt.all() as unknown as AttendanceRow[];
}

export function getAttendanceById(musicianId: number, rehearsalId: number): AttendanceRow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM attendance WHERE musician_id = ? AND rehearsal_id = ?"
  );
  return stmt.get(musicianId, rehearsalId) as unknown as AttendanceRow | undefined;
}

export function insertAttendance(
  musicianId: number,
  rehearsalId: number,
  status: "present" | "absent" | "late"
): number {
  const stmt = db.prepare(
    "INSERT INTO attendance (musician_id, rehearsal_id, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(musicianId, rehearsalId, status);
  return Number(result.lastInsertRowid);
}

export function updateAttendance(
  musicianId: number,
  rehearsalId: number,
  status: "present" | "absent" | "late"
): number {
  const stmt = db.prepare(
    "UPDATE attendance SET status = ? WHERE musician_id = ? AND rehearsal_id = ?"
  );
  const result = stmt.run(status, musicianId, rehearsalId);
  return Number(result.changes);
}

export function deleteAttendance(musicianId: number, rehearsalId: number): number {
  const stmt = db.prepare(
    "DELETE FROM attendance WHERE musician_id = ? AND rehearsal_id = ?"
  );
  const result = stmt.run(musicianId, rehearsalId);
  return Number(result.changes);
}

