export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  if (!(req.path.startsWith("/export") && req.method === "POST")) {
    next();
    return;
  }

  // Check if user is owner (this is a placeholder implementation)
  // In a real system, this would check the user's role/permissions
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Export access denied. Owner only." });
    return;
  }

  next();
}

