export function RehearsalScheduleView() {
  const [rehearsals, setRehearsals] = useState<Rehearsal[]>([]);
  const [attendances, setAttendances] = useState<Record<string, Attendance>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [musicianId] = useState("musician-123"); // In a real app, this would come from auth

  useEffect(() => {
    async function fetchRehearsals() {
      try {
        const response = await fetch(`/api/rehearsal-api/rehearsals`);
        if (!response.ok) throw new Error(`Failed to fetch rehearsals: ${response.status}`);
        const data = await response.json();
        setRehearsals(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    async function fetchAttendances() {
      try {
        const response = await fetch(`/api/rehearsal-api/attendances`);
        if (!response.ok) throw new Error(`Failed to fetch attendances: ${response.status}`);
        const data = await response.json();
        const attendanceMap: Record<string, Attendance> = {};
        data.forEach((att: Attendance) => {
          attendanceMap[`${att.musicianId}-${att.rehearsalId}`] = att;
        });
        setAttendances(attendanceMap);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    }

    fetchRehearsals();
    fetchAttendances();
  }, []);

  const handleAttendanceChange = async (rehearsalId: string, status: "present" | "absent" | "late") => {
    const key = `${musicianId}-${rehearsalId}`;
    const existing = attendances[key];

    try {
      if (existing) {
        const response = await fetch(
          `/api/rehearsal-api/attendances/${musicianId}/${rehearsalId}`,
          {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ status }),
          }
        );
        if (!response.ok) throw new Error(`Failed to update attendance: ${response.status}`);
      } else {
        const response = await fetch(`/api/rehearsal-api/attendances`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ musicianId, rehearsalId, status }),
        });
        if (!response.ok) throw new Error(`Failed to create attendance: ${response.status}`);
      }

      // Update local state
      setAttendances(prev => ({
        ...prev,
        [key]: { rehearsalId, musicianId, status }
      }));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  if (rehearsals.length === 0) {
    return (
      <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
        <h2>Upcoming Rehearsals</h2>
        <p>No rehearsals scheduled.</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
