import { Router, type Request, type Response } from "express";
import { db, deleteSession, getAllSessions, getSessionById, insertSession, updateSession } from "../db/sessions-table";

export const router = Router();

// Get all sessions
router.get("/", (req: Request, res: Response) => {
  const sessions = getAllSessions();
  res.json(sessions);
});

// Get a session by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const session = getSessionById(id);

  if (!session) {
    return res.status(404).json({ error: "Session not found" });
  }

  res.json(session);
});

// Create a new session
router.post("/", (req: Request, res: Response) => {
  const { tutorId, studentId, topic, timestamp } = req.body;

  if (!tutorId || !studentId || !topic || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const id = insertSession(tutorId, studentId, topic, timestamp);
  const newSession = getSessionById(id);

  if (!newSession) {
    return res.status(500).json({ error: "Failed to create session" });
  }

  res.status(201).json(newSession);
});

// Update a session
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { tutorId, studentId, topic, timestamp } = req.body;

  if (!tutorId || !studentId || !topic || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingSession = getSessionById(id);

  if (!existingSession) {
    return res.status(404).json({ error: "Session not found" });
  }

  updateSession(id, tutorId, studentId, topic, timestamp);
  const updatedSession = getSessionById(id);

  if (!updatedSession) {
    return res.status(500).json({ error: "Failed to update session" });
  }

  res.json(updatedSession);
});

// Delete a session
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingSession = getSessionById(id);

  if (!existingSession) {
    return res.status(404).json({ error: "Session not found" });
  }

  deleteSession(id);

  res.json({ message: "Session deleted successfully" });
});

