import { Router, type Request, type Response } from "express";
import { getSubmissionById } from "../db/submissions-table";
import { getExportById } from "../db/exports-table";

export const router = Router();

router.post("/export/:id", (req: Request, res: Response) => {
  const exportId = Number(req.params.id);
  const authorId = Number(req.body.authorId);

  if (isNaN(exportId) || isNaN(authorId)) {
    return res.status(400).json({ error: "Invalid export ID or author ID" });
  }

  const exportRecord = getExportById(exportId);
  if (!exportRecord) {
    return res.status(404).json({ error: "Export record not found" });
  }

  if (exportRecord.authorId !== authorId) {
    return res.status(403).json({ error: "Access denied: not the owner" });
  }

  // If we reach here, the user is authorized to export
  return res.status(200).json({ message: "Export authorized" });
});

import type { Request, Response, NextFunction } from "express";
import { router as submissionsRouter } from "../routes/submissions-api";
import { router as exportGuardRouter } from "../routes/export-guard-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export requests
  if (!(req.method === "POST" && req.path.startsWith("/export"))) {
    next();
    return;
  }

  // Check if user is owner (this is a placeholder implementation)
  // In a real system, this would check the user's ownership status
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Forbidden: Only owners can export" });
    return;
  }

  next();
}

