export function ExportHistoryGuard() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [exports, setExports] = useState<Export[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const userResponse = await fetch('/api/user');
        if (!userResponse.ok) throw new Error('Failed to fetch user data');
        const userData = await userResponse.json();
        setCurrentUserId(userData.id);
      } catch (err) {
        setError('Failed to load user data');
        setLoading(false);
      }
    };

    const fetchSubmissions = async () => {
      try {
        const response = await fetch('/api/submissions-api/submissions');
        if (!response.ok) throw new Error('Failed to fetch submissions');
        const data = await response.json();
        setSubmissions(data);
      } catch (err) {
        setError('Failed to load submissions');
      } finally {
        setLoading(false);
      }
    };

    const fetchExports = async () => {
      try {
        const response = await fetch('/api/submissions-api/exports');
        if (!response.ok) throw new Error('Failed to fetch exports');
        const data = await response.json();
        setExports(data);
      } catch (err) {
        setError('Failed to load exports');
      }
    };

    fetchUserData();
    fetchSubmissions();
    fetchExports();
  }, []);

  const handleExport = async (submissionId: string) => {
    try {
      const response = await fetch(`/api/export-guard-service/export/${submissionId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) throw new Error('Export failed');

      // Refresh data after successful export
      const submissionsResponse = await fetch('/api/submissions-api/submissions');
      const exportsResponse = await fetch('/api/submissions-api/exports');

      if (submissionsResponse.ok && exportsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        const exportsData = await exportsResponse.json();

        setSubmissions(submissionsData);
        setExports(exportsData);
      }
    } catch (err) {
      setError('Export failed');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Export History</h1>

      {submissions.length === 0 ? (
        <p>No submissions found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '10px' }}>Title</th>
              <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {submissions.map((submission) => {
              const hasExport = exports.some(e => e.submissionId === submission.id);
              const canExport = currentUserId === submission.authorId;

              return (
                <tr key={submission.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{submission.title}</td>
                  <td style={{ padding: '10px' }}>
                    {canExport && !hasExport ? (
                      <button 
                        onClick={() => handleExport(submission.id)}
                        style={{ 
                          backgroundColor: '#007bff', 
                          color: 'white', 
                          border: 'none', 
                          borderRadius: '4px', 
                          padding: '8px 12px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Export
                      </button>
                    ) : null}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

