import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface AgingBatch {
  id: number;
  cheese_type: string;
  age_days: number;
  owner_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS aging_batches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cheese_type TEXT NOT NULL,
    age_days INTEGER NOT NULL,
    owner_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBatches(): AgingBatch[] {
  const stmt = db.prepare(`SELECT * FROM aging_batches`);
  return stmt.all() as unknown as AgingBatch[];
}

export function getBatchById(id: number): AgingBatch | undefined {
  const stmt = db.prepare(`SELECT * FROM aging_batches WHERE id = ?`);
  return stmt.get(id) as unknown as AgingBatch | undefined;
}

export function insertBatch(
  cheeseType: string,
  ageDays: number,
  ownerId: number
): number {
  const stmt = db.prepare(
    `INSERT INTO aging_batches (cheese_type, age_days, owner_id) VALUES (?, ?, ?)`
  );
  const result = stmt.run(cheeseType, ageDays, ownerId);
  return Number(result.lastInsertRowid);
}

export function updateBatch(
  id: number,
  cheeseType: string,
  ageDays: number,
  ownerId: number
): void {
  const stmt = db.prepare(
    `UPDATE aging_batches SET cheese_type = ?, age_days = ?, owner_id = ? WHERE id = ?`
  );
  stmt.run(cheeseType, ageDays, ownerId, id);
}

export function deleteBatch(id: number): void {
  const stmt = db.prepare(`DELETE FROM aging_batches WHERE id = ?`);
  stmt.run(id);
}

