import { Router, type Request, type Response } from "express";
import { getAllBatches } from "../db/aging-batches-table";

export const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Extract ownerId from query parameters
  const ownerIdParam = req.query.ownerId;

  if (!ownerIdParam) {
    return res.status(400).json({ error: "Missing ownerId parameter" });
  }

  const ownerId = Number(ownerIdParam);

  if (isNaN(ownerId)) {
    return res.status(400).json({ error: "Invalid ownerId parameter" });
  }

  // Get all batches from the database
  const batches = getAllBatches();

  // Filter batches by ownerId
  const userBatches = batches.filter(batch => batch.owner_id === ownerId);

  // Generate CSV content
  const csvContent = [
    "id,cheese_type,age_days,owner_id",
    ...userBatches.map(batch => `${batch.id},${batch.cheese_type},${batch.age_days},${batch.owner_id}`)
  ].join("\n");

  // Set response headers for CSV download
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=cheese_aging_data.csv");

  // Send the CSV content
  res.send(csvContent);
});

import type { Request, Response, NextFunction } from "express";
import { Router } from "express";
import { router as agingBatchRouter } from "../routes/aging-batch-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export requests
  if (!(req.path.startsWith("/export") && req.method === "POST")) {
    next();
    return;
  }

  // Check if user is owner
  // This is a placeholder implementation - in reality, this would
  // check the request context for ownership information
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Only the owner can export" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Batch {
  id: number;
  cheeseType: string;
  startDate: string;
  endDate?: string;
  status: 'aging' | 'completed' | 'failed';
}

export function BatchLogForm() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    cheeseType: '',
    startDate: '',
    status: 'aging' as 'aging' | 'completed' | 'failed',
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/aging-batch-api/');
      if (!response.ok) throw new Error('Failed to fetch batches');
      const data = await response.json();
      setBatches(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const url = editingId 
        ? `/api/aging-batch-api/${editingId}`
        : '/api/aging-batch-api/';
      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!response.ok) throw new Error('Failed to save batch');

      fetchBatches();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (batch: Batch) => {
    setFormData({
      cheeseType: batch.cheeseType,
      startDate: batch.startDate,
      status: batch.status,
    });
    setEditingId(batch.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/aging-batch-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Failed to delete batch');
      fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const resetForm = () => {
    setFormData({
      cheeseType: '',
      startDate: '',
      status: 'aging',
    });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Batch Log Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Cheese Type:</label>
          <input
            type="text"
            value={formData.cheeseType}
            onChange={(e) => setFormData({...formData, cheeseType: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Start Date:</label>
          <input
            type="date"
            value={formData.startDate}
            onChange={(e) => setFormData({...formData, startDate: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Status:</label>
          <select
            value={formData.status}
            onChange={(e) => setFormData({...formData, status: e.target.value as any})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
          >
            <option value="aging">Aging</option>
            <option value="completed">Completed</option>
            <option value="failed">Failed</option>
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          {editingId ? 'Update Batch' : 'Add Batch'}
        </button>

        {editingId && (
          <button 
            type="button" 
            onClick={resetForm}
            style={{ 
              backgroundColor: '#6c757d', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
              cursor: 'pointer', 
              marginLeft: '10px' 
            }}
          >
            Cancel Edit
          </button>
        )}
      </form>

      <h2 style={{ textAlign: 'center' }}>Aging Batches</h2>

      {batches.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No batches found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {batches.map(batch => (
            <div 
              key={batch.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center' 
              }}
            >
              <div>
                <strong>{batch.cheeseType}</strong> - {batch.startDate}
                <br />
                Status: {batch.status}
              </div>
              <div>
                <button 
                  onClick={() => handleEdit(batch)}
                  style={{ 
                    backgroundColor: '#17a2b8', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer', 
                    marginRight: '5px' 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(batch.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { FC, useEffect, useState } from "react";

