export function OwnerOnlyExportButton() {
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [hasAccess, setHasAccess] = useState<boolean>(false);

  useEffect(() => {
    // Simulate checking if user has owner access
    // In a real app, this would be an API call to verify user role
    const checkAccess = async () => {
      try {
        // Mock access check - in reality this would be a call to authenticate user
        // For demo purposes, we'll assume owner access
        setHasAccess(true);
      } catch (err) {
        setError("Failed to verify access");
      } finally {
        setIsLoading(false);
      }
    };

    checkAccess();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch("/api/export-service/export", {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "cheese-aging-data.csv";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError("Export failed: " + (err as Error).message);
    }
  };

  if (isLoading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  if (!hasAccess) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Access denied</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
      <h2>Owner-Only Export Button</h2>
      <p>This button is only visible to owners.</p>
      <button 
        onClick={handleExport}
        style={{
          backgroundColor: "#4CAF50",
          border: "none",
          color: "white",
          padding: "15px 32px",
          textAlign: "center",
          textDecoration: "none",
          display: "inline-block",
          fontSize: "16px",
          margin: "4px 2px",
          cursor: "pointer",
          borderRadius: "8px",
        }}
      >
        Export All Data
      </button>
    </div>
  );
}

