import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Order {
  id: number;
  customerId: number;
  flavour: string;
  size: string;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    customerId INTEGER NOT NULL,
    flavour TEXT NOT NULL,
    size TEXT NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllOrders(): Order[] {
  const stmt = db.prepare("SELECT * FROM orders");
  return stmt.all() as unknown as Order[];
}

export function getOrderById(id: number): Order | undefined {
  const stmt = db.prepare("SELECT * FROM orders WHERE id = ?");
  return stmt.get(id) as unknown as Order | undefined;
}

export function insertOrder(order: Omit<Order, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO orders (customerId, flavour, size, date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(order.customerId, order.flavour, order.size, order.date);
  return Number(result.lastInsertRowid);
}

export function updateOrder(id: number, order: Partial<Omit<Order, "id">>): boolean {
  const fields = [];
  const values = [];

  if (order.customerId !== undefined) {
    fields.push("customerId = ?");
    values.push(order.customerId);
  }

  if (order.flavour !== undefined) {
    fields.push("flavour = ?");
    values.push(order.flavour);
  }

  if (order.size !== undefined) {
    fields.push("size = ?");
    values.push(order.size);
  }

  if (order.date !== undefined) {
    fields.push("date = ?");
    values.push(order.date);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE orders SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteOrder(id: number): boolean {
  const stmt = db.prepare("DELETE FROM orders WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

