import type { Request, Response, NextFunction } from "express";
import { router as ordersRouter } from "../routes/orders-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply privacy guard to order-related routes
  if (!req.path.startsWith("/api/orders")) {
    next();
    return;
  }

  // For GET requests to order endpoints, check if user is authorized
  if (req.method === "GET") {
    // This is a simplified check - in reality, you'd want to verify
    // the user's identity and permissions against the order ID
    // For now, we'll just pass through to let the route handler
    // deal with authorization logic
    next();
    return;
  }

  // For non-GET methods, continue normally (let route handlers decide)
  next();
}

import { useEffect, useState } from "react";

interface CakeOrder {
  id?: number;
  flavor: string;
  size: string;
  decorations: string;
  specialInstructions: string;
}

export function OrderForm() {
  const [orders, setOrders] = useState<CakeOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<Omit<CakeOrder, 'id'>>({ 
    flavor: '',
    size: '',
    decorations: '',
    specialInstructions: ''
  });

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/orders-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch orders: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/orders-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      if (!response.ok) {
        throw new Error(`Failed to create order: ${response.status} ${response.statusText}`);
      }
      // Reset form
      setFormData({ flavor: '', size: '', decorations: '', specialInstructions: '' });
      // Refresh orders
      await fetchOrders();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Custom Cake Order</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="flavor" style={{ display: 'block', marginBottom: '5px' }}>Flavor:</label>
          <input
            type="text"
            id="flavor"
            name="flavor"
            value={formData.flavor}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="size" style={{ display: 'block', marginBottom: '5px' }}>Size:</label>
          <input
            type="text"
            id="size"
            name="size"
            value={formData.size}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="decorations" style={{ display: 'block', marginBottom: '5px' }}>Decorations:</label>
          <input
            type="text"
            id="decorations"
            name="decorations"
            value={formData.decorations}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="specialInstructions" style={{ display: 'block', marginBottom: '5px' }}>Special Instructions:</label>
          <textarea
            id="specialInstructions"
            name="specialInstructions"
            value={formData.specialInstructions}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd', minHeight: '80px' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            padding: '10px 20px', 
            border: 'none', 
            borderRadius: '4px', 
            cursor: 'pointer', 
            fontSize: '16px' 
          }}
        >
          Submit Order
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Your Orders</h2>

      {orders.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No orders yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {orders.map(order => (
            <div 
              key={order.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: '#f9f9f9'
              }}
            >
              <div><strong>Flavor:</strong> {order.flavor}</div>
              <div><strong>Size:</strong> {order.size}</div>
              <div><strong>Decorations:</strong> {order.decorations || 'None'}</div>
              <div><strong>Special Instructions:</strong> {order.specialInstructions || 'None'}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

