  insertShift("2023-06-16", 6);
  insertShift("2023-06-17", 5);
  insertShift("2023-06-18", 3);
  insertShift("2023-06-19", 7);
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-pool.db");

interface BookingRow {
  id: number;
  lifeguard_id: number;
  shift_id: number;
  status: "confirmed" | "pending" | "cancelled";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    lifeguard_id INTEGER NOT NULL,
    shift_id INTEGER NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('confirmed', 'pending', 'cancelled'))
  )
`;

db.exec(createTableSql);

export function getAllBookings(): BookingRow[] {
  const stmt = db.prepare("SELECT * FROM bookings");
  return stmt.all() as unknown as BookingRow[];
}

export function getBookingById(id: number): BookingRow | undefined {
  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as BookingRow | undefined;
}

export function createBooking(
  lifeguardId: number,
  shiftId: number,
  status: "confirmed" | "pending" | "cancelled"
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (lifeguard_id, shift_id, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(lifeguardId, shiftId, status);
  return Number(result.lastInsertRowid);
}

export function updateBooking(
  id: number,
  lifeguardId: number,
  shiftId: number,
  status: "confirmed" | "pending" | "cancelled"
): void {
  const stmt = db.prepare(
    "UPDATE bookings SET lifeguard_id = ?, shift_id = ?, status = ? WHERE id = ?"
  );
  stmt.run(lifeguardId, shiftId, status, id);
}

export function deleteBooking(id: number): void {
  const stmt = db.prepare("DELETE FROM bookings WHERE id = ?");
  stmt.run(id);
}

