export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newBooking, setNewBooking] = useState({
    shiftId: '',
    lifeguardName: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [shiftsResponse, bookingsResponse] = await Promise.all([
          fetch('/api/shift-booking-api/shifts'),
          fetch('/api/shift-booking-api/bookings')
        ]);

        if (!shiftsResponse.ok || !bookingsResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const shiftsData = await shiftsResponse.json();
        const bookingsData = await bookingsResponse.json();

        setShifts(shiftsData);
        setBookings(bookingsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleClaimShift = async (shiftId: string) => {
    if (!newBooking.lifeguardName.trim()) {
      setError('Please enter your name');
      return;
    }

    try {
      const response = await fetch('/api/shift-booking-api/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          shiftId,
          lifeguardName: newBooking.lifeguardName
        })
      });

      if (!response.ok) {
        throw new Error('Failed to book shift');
      }

      // Refresh data
      const [shiftsResponse, bookingsResponse] = await Promise.all([
        fetch('/api/shift-booking-api/shifts'),
        fetch('/api/shift-booking-api/bookings')
      ]);

      if (!shiftsResponse.ok || !bookingsResponse.ok) {
        throw new Error('Failed to refresh data');
      }

      const shiftsData = await shiftsResponse.json();
      const bookingsData = await bookingsResponse.json();

      setShifts(shiftsData);
      setBookings(bookingsData);
      setNewBooking({ shiftId: '', lifeguardName: '' });
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const getOpenShifts = () => {
    const bookedShiftIds = new Set(bookings.map(b => b.shiftId));
    return shifts.filter(shift => !bookedShiftIds.has(shift.id));
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  const openShifts = getOpenShifts();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Shift Claim Board</h1>

      {openShifts.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No open shifts available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {openShifts.map(shift => (
            <div key={shift.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span><strong>Date:</strong> {shift.date}</span>
                <span><strong>Location:</strong> {shift.location}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span><strong>Start:</strong> {shift.startTime}</span>
                <span><strong>End:</strong> {shift.endTime}</span>
              </div>
              <button 
                onClick={() => handleClaimShift(shift.id)}
                style={{ 
                  backgroundColor: '#007bff', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: 'pointer' 
                }}
              >
                Claim Shift
              </button>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: '30px', borderTop: '1px solid #eee', paddingTop: '20px' }}>
        <h2 style={{ textAlign: 'center' }}>Book a Shift</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Your Name"
            value={newBooking.lifeguardName}
            onChange={(e) => setNewBooking({...newBooking, lifeguardName: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
          <button 
            onClick={() => {
              if (newBooking.shiftId && newBooking.lifeguardName.trim()) {
                handleClaimShift(newBooking.shiftId);
              }
            }}
            style={{ 
              backgroundColor: '#28a745', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              padding: '10px', 
              cursor: 'pointer' 
            }}
          >
            Book Selected Shift
          </button>
        </div>
      </div>
    </div>
  );
}

