import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./brewer-keg-inventory.db"
);

interface KegFill {
  id: number;
  brewer_id: number;
  keg_size: string;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS keg_fills (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    brewer_id INTEGER NOT NULL,
    keg_size TEXT NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllKegFills(): KegFill[] {
  const stmt = db.prepare(`SELECT * FROM keg_fills`);
  return stmt.all() as unknown as KegFill[];
}

export function getKegFillById(id: number): KegFill | undefined {
  const stmt = db.prepare(
    `SELECT * FROM keg_fills WHERE id = ?`
  );
  return stmt.get(id) as unknown as KegFill | undefined;
}

export function insertKegFill(
  brewerId: number,
  kegSize: string,
  date: string
): number {
  const stmt = db.prepare(
    `INSERT INTO keg_fills (brewer_id, keg_size, date) VALUES (?, ?, ?)`
  );
  const result = stmt.run(brewerId, kegSize, date);
  return Number(result.lastInsertRowid);
}

export function updateKegFill(
  id: number,
  brewerId: number,
  kegSize: string,
  date: string
): void {
  const stmt = db.prepare(
    `UPDATE keg_fills SET brewer_id = ?, keg_size = ?, date = ? WHERE id = ?`
  );
  stmt.run(brewerId, kegSize, date, id);
}

export function deleteKegFill(id: number): void {
  const stmt = db.prepare(`DELETE FROM keg_fills WHERE id = ?`);
  stmt.run(id);
}

