import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply scope checking to GET requests to /members/:id
  if (req.method !== "GET" || !req.path.startsWith("/members/")) {
    next();
    return;
  }

  // Extract user ID from request (assuming it's set by auth middleware)
  const authenticatedUserId = (req as any).user?.id;

  // If no authenticated user, allow request to proceed (let other middleware handle it)
  if (!authenticatedUserId) {
    next();
    return;
  }

  // Extract target member ID from URL path
  const pathParts = req.path.split("/");
  const targetMemberId = pathParts[3];

  // If no target member ID, allow request to proceed
  if (!targetMemberId) {
    next();
    return;
  }

  // Check if the authenticated user is trying to access their own data
  if (authenticatedUserId === targetMemberId) {
    next();
    return;
  }

  // If the authenticated user is not accessing their own data, reject the request
  res.status(403).json({ error: "Forbidden: Access denied" });
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface MachineReport {
  id: number;
  memberId: number;
  machineId: number;
  reportText: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS machine_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    machineId INTEGER NOT NULL,
    reportText TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllMachineReports(): MachineReport[] {
  const stmt = db.prepare(`SELECT * FROM machine_reports`);
  return stmt.all() as unknown as MachineReport[];
}

export function getMachineReportById(id: number): MachineReport | undefined {
  const stmt = db.prepare(`SELECT * FROM machine_reports WHERE id = ?`);
  return stmt.get(id) as unknown as MachineReport | undefined;
}

export function insertMachineReport(
  memberId: number,
  machineId: number,
  reportText: string
): number {
  const stmt = db.prepare(
    `INSERT INTO machine_reports (memberId, machineId, reportText) VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, machineId, reportText);
  return Number(result.lastInsertRowid);
}

export function updateMachineReport(
  id: number,
  memberId: number,
  machineId: number,
  reportText: string
): number {
  const stmt = db.prepare(
    `UPDATE machine_reports SET memberId = ?, machineId = ?, reportText = ? WHERE id = ?`
  );
  const result = stmt.run(memberId, machineId, reportText, id);
  return Number(result.changes);
}

export function deleteMachineReport(id: number): number {
  const stmt = db.prepare(`DELETE FROM machine_reports WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

