import { Router, type Request, type Response } from "express";
import {
  db,
  deleteMachineReport,
  getAllMachineReports,
  getMachineReportById,
  insertMachineReport,
  updateMachineReport
} from "../db/machine-reports-table";

export const router = Router();

// Get all machine reports
router.get("/", (req: Request, res: Response) => {
  try {
    const reports = getAllMachineReports();
    res.json(reports);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch machine reports" });
  }
});

// Get a specific machine report by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    const report = getMachineReportById(id);
    if (!report) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json(report);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch machine report" });
  }
});

// Create a new machine report
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, machineId, reportText } = req.body;

    if (!memberId || !machineId || !reportText) {
      return res.status(400).json({ error: "Missing required fields: memberId, machineId, reportText" });
    }

    const newId = insertMachineReport(memberId, machineId, reportText);
    const createdReport = getMachineReportById(newId);

    if (!createdReport) {
      return res.status(500).json({ error: "Failed to create machine report" });
    }

    res.status(201).json(createdReport);
  } catch (error) {
    res.status(500).json({ error: "Failed to create machine report" });
  }
});

// Update an existing machine report
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, machineId, reportText } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    if (!memberId || !machineId || !reportText) {
      return res.status(400).json({ error: "Missing required fields: memberId, machineId, reportText" });
    }

    const updatedId = updateMachineReport(id, memberId, machineId, reportText);
    const updatedReport = getMachineReportById(updatedId);

    if (!updatedReport) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json(updatedReport);
  } catch (error) {
    res.status(500).json({ error: "Failed to update machine report" });
  }
});

// Delete a machine report
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    const deletedId = deleteMachineReport(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json({ message: "Machine report deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete machine report" });
  }
});

import { useEffect, useState } from "react";

interface MachineReport {
  id: number;
  machineId: number;
  description: string;
  reportedAt: string;
}

export function MachineReportForm() {
  const [reports, setReports] = useState<MachineReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [machineId, setMachineId] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/machine-reports-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setReports(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/machine-reports-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          machineId: Number(machineId),
          description,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Reset form
      setMachineId("");
      setDescription("");

      // Refresh reports
      await fetchReports();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>Error: {error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Report Broken Machine</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="machineId" style={{ display: 'block', marginBottom: '5px' }}>
            Machine ID
          </label>
          <input
            id="machineId"
            type="number"
            value={machineId}
            onChange={(e) => setMachineId(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="description" style={{ display: 'block', marginBottom: '5px' }}>
            Description
          </label>
          <textarea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', minHeight: '100px' }}
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Submit Report
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Recent Reports</h2>

      {reports.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No reports found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {reports.map(report => (
            <div 
              key={report.id} 
              style={{ 
                padding: '15px', 
                border: '1px solid #ccc', 
                borderRadius: '8px' 
              }}
            >
              <div><strong>Machine ID:</strong> {report.machineId}</div>
              <div><strong>Description:</strong> {report.description}</div>
              <div><strong>Reported At:</strong> {new Date(report.reportedAt).toLocaleString()}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

